import subprocess, time, sys
SESS="testx"
def cap(e=False):
    args=["tmux","capture-pane","-p","-t",SESS]
    if e: args.insert(3,"-e")
    try:
        return subprocess.check_output(args).decode()
    except Exception as ex:
        return f"<err {ex}>"
def start(cmd,w=120,h=40):
    subprocess.run(["tmux","kill-session","-t",SESS], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    subprocess.run(["tmux","new-session","-d","-s",SESS,"-x",str(w),"-y",str(h),cmd], check=True)
    time.sleep(0.8)
def send(*keys):
    for k in keys:
        if isinstance(k,tuple):
            subprocess.run(["tmux","send-keys","-t",SESS]+list(k))
        else:
            subprocess.run(["tmux","send-keys","-t",SESS,k])
        time.sleep(0.4)
def show(label=""):
    print(f"=== {label} ===")
    print(cap())
    print("=== END ===")
def stop():
    subprocess.run(["tmux","kill-session","-t",SESS], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

if __name__=="__main__":
    cmd=sys.argv[1] if len(sys.argv)>1 else "./executable /tmp/test1.txt"
    start(cmd, w=int(sys.argv[2]) if len(sys.argv)>2 else 120, h=int(sys.argv[3]) if len(sys.argv)>3 else 40)
    show("initial")
    send("q")
    time.sleep(0.5)
    print("after q alive?")
    print(cap())
    stop()
