            elif a=="Space": send_key("Space")
            elif a in ("Up","Down","Left","Right"): send_key(a)
            else: send_key(a)
        else:
            # string literal typed
            # if starts with KEY: ?
            if isinstance(a, tuple) and a[0]=="key":
                send_key(a[1]); label=str(a)
            elif isinstance(a, tuple) and a[0]=="text":
                send_text(a[1]); label=str(a)
            else:
                send_text(str(a))
        show(f"after {label!r}")
    stop()

if __name__=="__main__":
    pass
