import sys; sys.path.insert(0,'/tmp')
from h2 import *
import time
def get_lines():
    return cap().splitlines()
def selected_line():
    ls=get_lines()
    # in flame view selected is line after "Selected ---"
    for i,l in enumerate(ls):
        if l.startswith("Selected"):
            return ls[i+1] if i+1<len(ls) else ""
    return "(no selected) | "+" | ".join(ls[3:10])
def run(cmd, actions, w=120, h=40, label_rows=None):
    start_shell(w,h)
    run_cmd(cmd, wait=0.9)
    print("INIT selected:", selected_line())
    if label_rows:
        for r in get_lines()[label_rows[0]:label_rows[1]]: print(" ",r)
    for a in actions:
        if isinstance(a, tuple) and a[0]=="key":
            send_key(a[1])
        elif isinstance(a, tuple) and a[0]=="text":
            send_text(a[1])
        elif a in ("Enter","Escape","Tab","BSpace","Space","Up","Down","Left","Right","C-c"):
            send_key(a)
        else:
            # single char via send-keys name? Use send_text for printable, but special chars like '/' need ?
            send_text(str(a))
        print(f"after {a!r} selected:", selected_line())
        if label_rows:
            txt=get_lines()
            for r in txt[label_rows[0]:label_rows[1]]: print(" ",r)
    stop()
