use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};

fn fnv1a64(bytes:&[u8]) -> u64 { let mut h=0xcbf29ce484222325u64; for &b in bytes { h ^= b as u64; h=h.wrapping_mul(0x100000001b3); } h }
fn fnv1_64(bytes:&[u8]) -> u64 { let mut h=0xcbf29ce484222325u64; for &b in bytes { h=h.wrapping_mul(0x100000001b3); h ^= b as u64; } h }
fn fnv1a32(bytes:&[u8]) -> u64 { let mut h=0x811c9dc5u32; for &b in bytes { h ^= b as u32; h=h.wrapping_mul(0x01000193); } h as u64 }
fn djb2(bytes:&[u8]) -> u64 { let mut h=5381u64; for &b in bytes { h=h.wrapping_mul(33).wrapping_add(b as u64); } h }
fn djb2xor(bytes:&[u8]) -> u64 { let mut h=5381u64; for &b in bytes { h=h.wrapping_mul(33) ^ (b as u64); } h }
fn sdbm(bytes:&[u8]) -> u64 { let mut h=0u64; for &b in bytes { h=(b as u64).wrapping_add(h.wrapping_mul(65599)); } h }
fn crc32(bytes:&[u8]) -> u64 {
    // IEEE
    let mut crc=0xffffffffu32;
    for &b in bytes {
        crc ^= b as u32;
        for _ in 0..8 { crc = if crc&1!=0 { (crc>>1)^0xEDB88320 } else { crc>>1 }; }
    }
    (!crc) as u64
}
fn main(){
    let args:Vec<String>=std::env::args().collect();
    // print name then many hashes
    for name in &args[1..] {
        let mut h=DefaultHasher::new(); name.hash(&mut h); let dh=h.finish();
        let mut h2=DefaultHasher::new(); name.as_bytes().hash(&mut h2); let dhb=h2.finish(); // slice? Vec?
        // Hash for str in Rust: hash_slice? Actually <str>::hash writes bytes then 0xff. String same.
        // Also hash of (&str) ??? transparent?
        print!("{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}", name, dh, fnv1a64(name.as_bytes()), fnv1_64(name.as_bytes()), fnv1a32(name.as_bytes()), djb2(name.as_bytes()), djb2xor(name.as_bytes()), sdbm(name.as_bytes()), crc32(name.as_bytes()));
        // additional candidates prefixed all;
        for pref in ["all;", "all", "", ";"] {
            let s=format!("{}{}",pref,name);
            let mut hh=DefaultHasher::new(); s.hash(&mut hh);
            print!("\t{}", hh.finish());
        }
        println!();
    }
    let _=dhb;
}
