//! A small regular-expression engine.
//!
//! The engine intentionally covers the syntax that is useful for searching
//! frame names: literals, classes, groups, alternation, repetitions,
//! anchors, word boundaries, common escapes, inline flags and a handful of
//! Unicode properties.  It is a backtracking matcher: the expressions used
//! against (short) frame names are normally simple.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Flags {
    pub i: bool,
    pub m: bool,
    pub s: bool,
    pub x: bool,
    pub u: bool, // accepted, Unicode is always used here
    pub swap_greed: bool,
}

impl Default for Flags {
    fn default() -> Self {
        Flags { i: false, m: false, s: false, x: false, u: true, swap_greed: false }
    }
}

#[derive(Clone, Debug)]
enum ClassPred {
    Digit(bool),
    Word(bool),
    Space(bool),
    Prop(String, bool),
}

#[derive(Clone, Debug)]
enum ClassItem {
    Ch(char),
    Range(char, char),
    Pred(ClassPred),
    Posix(&'static str, bool),
    Nested(ClassDef),
}

#[derive(Clone, Debug)]
struct ClassDef {
    negated: bool,
    items: Vec<ClassItem>,
}

impl ClassDef {
    fn matches(&self, c: char, ci: bool) -> bool {
        let mut hit = false;
        for item in &self.items {
            let m = match item {
                ClassItem::Ch(x) => chars_eq(*x, c, ci),
                ClassItem::Range(a, b) => {
                    if (*a <= c && c <= *b) {
                        true
                    } else if ci {
                        // Try the common one-character case folds.
                        c.to_lowercase().count() == 1
                            && c.to_uppercase().count() == 1
                            && ((*a <= c.to_lowercase().next().unwrap()
                                && c.to_lowercase().next().unwrap() <= *b)
                                || (*a <= c.to_uppercase().next().unwrap()
                                    && c.to_uppercase().next().unwrap() <= *b))
                    } else {
                        false
                    }
                }
                ClassItem::Pred(p) => pred_matches(p, c),
                ClassItem::Posix(name, neg) => {
                    let v = posix_matches(name, c);
                    if *neg { !v } else { v }
                }
                ClassItem::Nested(n) => n.matches(c, ci),
            };
            if m {
                hit = true;
                break;
            }
        }
        if self.negated { !hit } else { hit }
    }
}

fn chars_eq(a: char, b: char, ci: bool) -> bool {
    if a == b {
        return true;
    }
    if !ci {
        return false;
    }
    a.to_lowercase().eq(b.to_lowercase()) || a.to_uppercase().eq(b.to_uppercase())
}

fn pred_matches(p: &ClassPred, c: char) -> bool {
    let v = match p {
        ClassPred::Digit(_) => c.is_numeric() && c.to_digit(10).is_some() || ('\u{660}' <= c && c <= '\u{669}') || c.is_numeric() && format!("{}", c).chars().all(|x| x.is_ascii_digit()),
        // The expression above is simplified below for ASCII fast path;
        // Unicode decimal digits in Rust are exactly the Nd category, which
        // `is_numeric` approximates closely for real-world symbol names.
        ClassPred::Word(_) => is_word_char(c),
        ClassPred::Space(_) => c.is_whitespace(),
        ClassPred::Prop(name, _) => prop_matches(name, c),
    };
    // Recompute digit strictly where possible and apply negation.
    let v = match p {
        ClassPred::Digit(_) => is_digit_char(c),
        _ => v,
    };
    match p {
        ClassPred::Digit(neg) | ClassPred::Word(neg) | ClassPred::Space(neg) | ClassPred::Prop(_, neg) => {
            if *neg { !v } else { v }
        }
    }
}

fn is_digit_char(c: char) -> bool {
    // char::is_numeric is broader than Nd; the common cases (and all ASCII)
    // are identical. Use a conservative approximation via to_digit for
    // ASCII plus the Unicode numeric property exposed by char.
    if c.is_ascii_digit() {
        return true;
    }
    // Non-ASCII decimal digits all satisfy is_numeric and are contiguous
    // script digit blocks; this approximation is sufficient in practice.
    c.is_numeric() && !matches!(c, '²' | '³' | '¹' | '¼' | '½' | '¾')
}

pub fn is_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_' || ('\u{200c}' <= c && c <= '\u{200d}')
}

fn posix_matches(name: &str, c: char) -> bool {
    match name {
        "alpha" => c.is_alphabetic(),
        "digit" => c.is_ascii_digit(),
        "alnum" => c.is_alphanumeric(),
        "space" => c.is_whitespace(),
        "upper" => c.is_uppercase(),
        "lower" => c.is_lowercase(),
        "xdigit" => c.is_ascii_hexdigit(),
        "punct" => c.is_ascii_punctuation(),
        "cntrl" => c.is_control(),
        "blank" => c == ' ' || c == '\t',
        "print" => !c.is_control(),
        "graph" => !c.is_control() && c != ' ',
        "ascii" => c.is_ascii(),
        "word" => is_word_char(c),
        _ => false,
    }
}

fn prop_matches(name: &str, c: char) -> bool {
    match name {
        "L" | "Letter" => c.is_alphabetic(),
        "Lu" | "Uppercase_Letter" => c.is_uppercase(),
        "Ll" | "Lowercase_Letter" => c.is_lowercase(),
        "Lt" => c.is_uppercase(), // titlecase is rare
        "Lm" | "Lo" | "Other_Letter" | "Modifier_Letter" => c.is_alphabetic(),
        "N" | "Number" => c.is_numeric(),
        "Nd" | "Decimal_Number" => is_digit_char(c),
        "Nl" | "Letter_Number" => c.is_numeric(),
        "No" | "Other_Number" => c.is_numeric(),
        "Alphabetic" | "Alpha" => c.is_alphabetic(),
        "White_Space" | "space" => c.is_whitespace(),
        "Uppercase" => c.is_uppercase(),
        "Lowercase" => c.is_lowercase(),
        "M" | "Mark" | "Mn" | "Mc" | "Me" => {
            ('\u{300}' <= c && c <= '\u{36f}') || ('\u{483}' <= c && c <= '\u{489}')
        }
        "P" | "Punctuation" => c.is_ascii_punctuation() || ('\u{2000}' <= c && c <= '\u{206f}'),
        "S" | "Symbol" => ('\u{2000}' <= c && c <= '\u{2bff}'),
        "Z" | "Separator" => c.is_whitespace(),
        "C" | "Other" => c.is_control(),
        "Cc" | "Control" => c.is_control(),
        "Any" => true,
        "Assigned" => true,
        _ => false,
    }
}

fn valid_prop(name: &str) -> bool {
    matches!(
        name,
        "L" | "Letter" | "Lu" | "Uppercase_Letter" | "Ll" | "Lowercase_Letter" | "Lt"
            | "Lm" | "Lo" | "Other_Letter" | "Modifier_Letter" | "N" | "Number" | "Nd"
            | "Decimal_Number" | "Nl" | "Letter_Number" | "No" | "Other_Number" | "Alphabetic"
            | "Alpha" | "White_Space" | "space" | "Uppercase" | "Lowercase" | "M" | "Mark"
            | "Mn" | "Mc" | "Me" | "P" | "Punctuation" | "S" | "Symbol" | "Z" | "Separator"
            | "C" | "Other" | "Cc" | "Control" | "Any" | "Assigned"
    )
}

#[derive(Clone, Debug)]
enum Ast {
    Empty,
    Char(char, bool), // char, case-insensitive at compile time
    Any(bool),        // dot, matches newline?
    Class(ClassDef, bool),
    StartText,
    EndText,
    StartLine,
    EndLine,
    WordBoundary(bool),
    Seq(Vec<Ast>),
    Alt(Vec<Ast>),
    Repeat { node: Box<Ast>, min: u32, max: Option<u32>, lazy: bool },
    Group(Box<Ast>),
}

pub struct Regex {
    ast: Ast,
    pattern: String,
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

type PResult<T> = Result<T, ()>;

impl Parser {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }
    fn peek2(&self) -> Option<char> {
        self.chars.get(self.pos + 1).copied()
    }
    fn next(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }
    fn eat(&mut self, c: char) -> bool {
        if self.peek() == Some(c) {
            self.pos += 1;
            true
        } else {
            false
        }
    }
    fn skip_x(&mut self, flags: Flags) {
        if !flags.x {
            return;
        }
        loop {
            match self.peek() {
                Some(c) if c.is_whitespace() => {
                    self.pos += 1;
                }
                Some('#') => {
                    while let Some(c) = self.peek() {
                        if c == '\n' {
                            break;
                        }
                        self.pos += 1;
                    }
                }
                _ => break,
            }
        }
    }

    fn parse_alt(&mut self, flags: Flags) -> PResult<Ast> {
        let mut branches = vec![self.parse_seq(flags)?];
        loop {
            self.skip_x(flags);
            if self.eat('|') {
                branches.push(self.parse_seq(flags)?);
            } else {
                break;
            }
        }
        if branches.len() == 1 {
            Ok(branches.pop().unwrap())
        } else {
            Ok(Ast::Alt(branches))
        }
    }

    fn parse_seq(&mut self, mut flags: Flags) -> PResult<Ast> {
        let mut items: Vec<Ast> = Vec::new();
        loop {
            self.skip_x(flags);
            match self.peek() {
                None | Some('|') | Some(')') => break,
                _ => {}
            }
            // Detect a scoped flag directive that is not a group, e.g. (?i)
            if self.peek() == Some('(') && self.peek2() == Some('?') {
                if let Some((new_flags, consumed_group)) = self.try_parse_flag_directive(flags)? {
                    if consumed_group {
                        // It was (?flags:...) or (?flags) handled in parse_atom.
                        // parse_atom will deal with it; fall through.
                    } else {
                        flags = new_flags;
                        continue;
                    }
                }
            }
            let atom = self.parse_atom(&mut flags)?;
            let atom = self.parse_repeats(atom, flags)?;
            items.push(atom);
        }
        Ok(Ast::Seq(items))
    }

    // Returns Ok(Some((flags, is_group))) if this looks like (?...) flag syntax.
    fn try_parse_flag_directive(&mut self, flags: Flags) -> PResult<Option<(Flags, bool)>> {
        // Only peek; do not consume unless it's exactly (?flags) .
        let save = self.pos;
        // chars: ( ? ...
        if self.chars.get(self.pos) != Some(&'(') || self.chars.get(self.pos + 1) != Some(&'?') {
            return Ok(None);
        }
        let mut i = self.pos + 2;
        // '(?P<' / '(?<' / '(?=' / '(?!' etc are not flag directives.
        match self.chars.get(i) {
            Some('P') | Some('<') | Some('=') | Some('!') => return Ok(None),
            _ => {}
        }
        let mut nf = flags;
        let mut negate = false;
        let mut saw_any = false;
        while let Some(&c) = self.chars.get(i) {
            match c {
                'i' => { nf.i = !negate; saw_any = true; }
                'm' => { nf.m = !negate; saw_any = true; }
                's' => { nf.s = !negate; saw_any = true; }
                'x' => { nf.x = !negate; saw_any = true; }
                'u' => { nf.u = !negate; saw_any = true; }
                'U' => { nf.swap_greed = !negate; saw_any = true; }
                'R' => { saw_any = true; }
                '-' => {
                    if negate { return Err(()); }
                    negate = true;
                }
                ')' => {
                    if !saw_any && !negate {
                        return Ok(None);
                    }
                    self.pos = i + 1;
                    return Ok(Some((nf, false)));
                }
                ':' => {
                    // Scoped group; let parse_atom handle it.
                    let _ = save;
                    return Ok(Some((flags, true)));
                }
                _ => return Ok(None),
            }
            i += 1;
        }
        Ok(None)
    }

    fn parse_repeats(&mut self, mut atom: Ast, flags: Flags) -> PResult<Ast> {
        loop {
            self.skip_x(flags);
            let (min, max) = match self.peek() {
                Some('*') => {
                    self.pos += 1;
                    (0, None)
                }
                Some('+') => {
                    self.pos += 1;
                    (1, None)
                }
                Some('?') => {
                    self.pos += 1;
                    (0, Some(1))
                }
                Some('{') => {
                    // Rust's regex rejects a malformed counted repetition.
                    let save = self.pos;
                    self.pos += 1;
                    let mut a = String::new();
                    while let Some(c) = self.peek() {
                        if c.is_ascii_digit() {
                            a.push(c);
                            self.pos += 1;
                        } else { break; }
                    }
                    if a.is_empty() {
                        return Err(());
                    }
                    let min: u32 = a.parse().map_err(|_| ())?;
                    let max;
                    if self.eat(',') {
                        if self.peek() == Some('}') {
                            max = None;
                        } else {
                            let mut b = String::new();
                            while let Some(c) = self.peek() {
                                if c.is_ascii_digit() {
                                    b.push(c);
                                    self.pos += 1;
                                } else { break; }
                            }
                            if b.is_empty() {
                                return Err(());
                            }
                            let bv: u32 = b.parse().map_err(|_| ())?;
                            max = Some(bv);
                        }
                    } else {
                        max = Some(min);
                    }
                    if !self.eat('}') {
                        let _ = save;
                        return Err(());
                    }
                    if let Some(mx) = max {
                        if mx < min { return Err(()); }
                    }
                    (min, max)
                }
                _ => break,
            };
            let mut lazy = false;
            if self.peek() == Some('?') {
                // A following '?' is the lazy marker (also permits a** etc.:
                // after consuming it as a quantifier marker, the loop can
                // apply another repetition).
                self.pos += 1;
                lazy = true;
            }
            if flags.swap_greed {
                lazy = !lazy;
            }
            atom = Ast::Repeat { node: Box::new(atom), min, max, lazy };
        }
        Ok(atom)
    }

    fn parse_atom(&mut self, flags: &mut Flags) -> PResult<Ast> {
        self.skip_x(*flags);
        let c = self.next().ok_or(())?;
        match c {
            '(' => {
                if self.peek() == Some('?') {
                    self.pos += 1;
                    match self.peek() {
                        Some('=') | Some('!') => return Err(()),
                        Some('<') => {
                            // (?<name>...) or lookbehind (?<= / (?<!
                            self.pos += 1;
                            match self.peek() {
                                Some('=') | Some('!') => return Err(()),
                                _ => {}
                            }
                            // named capture
                            let mut closed = false;
                            while let Some(ch) = self.next() {
                                if ch == '>' { closed = true; break; }
                                if !(ch.is_alphanumeric() || ch == '_' || ch == '.' || ch == '[' || ch == ']') {
                                    return Err(());
                                }
                            }
                            if !closed { return Err(()); }
                            let inner = self.parse_alt(*flags)?;
                            if !self.eat(')') { return Err(()); }
                            return Ok(Ast::Group(Box::new(inner)));
                        }
                        Some('P') => {
                            self.pos += 1;
                            if self.eat('<') {
                                let mut closed = false;
                                while let Some(ch) = self.next() {
                                    if ch == '>' { closed = true; break; }
                                }
                                if !closed { return Err(()); }
                                let inner = self.parse_alt(*flags)?;
                                if !self.eat(')') { return Err(()); }
                                return Ok(Ast::Group(Box::new(inner)));
                            } else {
                                return Err(());
                            }
                        }
                        _ => {
                            // (?flags) or (?flags:...)
                            let mut nf = *flags;
                            let mut negate = false;
                            let mut saw = false;
                            loop {
                                let ch = self.next().ok_or(())?;
                                match ch {
                                    'i' => nf.i = !negate,
                                    'm' => nf.m = !negate,
                                    's' => nf.s = !negate,
                                    'x' => nf.x = !negate,
                                    'u' => nf.u = !negate,
                                    'U' => nf.swap_greed = !negate,
                                    'R' => {}
                                    '-' => {
                                        if negate { return Err(()); }
                                        negate = true;
                                        continue;
                                    }
                                    ')' => {
                                        if !saw && !negate { return Err(()); }
                                        *flags = nf;
                                        return Ok(Ast::Empty);
                                    }
                                    ':' => {
                                        let inner = self.parse_alt(nf)?;
                                        if !self.eat(')') { return Err(()); }
                                        return Ok(Ast::Group(Box::new(inner)));
                                    }
                                    _ => return Err(()),
                                }
                                saw = true;
                            }
                        }
                    }
                }
                let inner = self.parse_alt(*flags)?;
                if !self.eat(')') { return Err(()); }
                Ok(Ast::Group(Box::new(inner)))
            }
            ')' => Err(()),
            '*' | '+' | '?' => Err(()),
            '[' => {
                let class = self.parse_class(flags.i)?;
                Ok(Ast::Class(class, flags.i))
            }
            '.' => Ok(Ast::Any(flags.s)),
            '^' => Ok(if flags.m { Ast::StartLine } else { Ast::StartText }),
            '$' => Ok(if flags.m { Ast::EndLine } else { Ast::EndText }),
            '\\' => self.parse_escape(flags),
            _ => Ok(Ast::Char(c, flags.i)),
        }
    }

    fn parse_escape(&mut self, flags: &Flags) -> PResult<Ast> {
        let c = self.next().ok_or(())?;
        match c {
            'd' => Ok(single_pred(ClassPred::Digit(false))),
            'D' => Ok(single_pred(ClassPred::Digit(true))),
            'w' => Ok(single_pred(ClassPred::Word(false))),
            'W' => Ok(single_pred(ClassPred::Word(true))),
            's' => Ok(single_pred(ClassPred::Space(false))),
            'S' => Ok(single_pred(ClassPred::Space(true))),
            'b' => Ok(Ast::WordBoundary(true)),
            'B' => Ok(Ast::WordBoundary(false)),
            'A' => Ok(Ast::StartText),
            'z' => Ok(Ast::EndText),
            'n' => Ok(Ast::Char('\n', false)),
            'r' => Ok(Ast::Char('\r', false)),
            't' => Ok(Ast::Char('\t', false)),
            'f' => Ok(Ast::Char('\u{c}', false)),
            'v' => Ok(Ast::Char('\u{b}', false)),
            'a' => Ok(Ast::Char('\u{7}', false)),
            'x' => {
                // \xHH or \x{...}
                if self.eat('{') {
                    let mut s = String::new();
                    while let Some(ch) = self.next() {
                        if ch == '}' { break; }
                        s.push(ch);
                    }
                    let v = u32::from_str_radix(&s, 16).map_err(|_| ())?;
                    Ok(Ast::Char(char::from_u32(v).ok_or(())?, false))
                } else {
                    let h1 = self.next().ok_or(())?;
                    let h2 = self.next().ok_or(())?;
                    if !h1.is_ascii_hexdigit() || !h2.is_ascii_hexdigit() { return Err(()); }
                    let v = u32::from_str_radix(&format!("{}{}", h1, h2), 16).map_err(|_| ())?;
                    Ok(Ast::Char(char::from_u32(v).ok_or(())?, false))
                }
            }
            'u' => {
                if self.eat('{') {
                    let mut s = String::new();
                    while let Some(ch) = self.next() {
                        if ch == '}' { break; }
                        s.push(ch);
                    }
                    let v = u32::from_str_radix(&s, 16).map_err(|_| ())?;
                    Ok(Ast::Char(char::from_u32(v).ok_or(())?, false))
                } else {
                    let mut s = String::new();
                    for _ in 0..4 {
                        let h = self.next().ok_or(())?;
                        if !h.is_ascii_hexdigit() { return Err(()); }
                        s.push(h);
                    }
                    let v = u32::from_str_radix(&s, 16).map_err(|_| ())?;
                    Ok(Ast::Char(char::from_u32(v).ok_or(())?, false))
                }
            }
            'p' | 'P' => {
                let neg = c == 'P';
                let name = if self.eat('{') {
                    let mut s = String::new();
                    while let Some(ch) = self.next() {
                        if ch == '}' { break; }
                        s.push(ch);
                    }
                    s
                } else {
                    let ch = self.next().ok_or(())?;
                    ch.to_string()
                };
                // Names may be like "L", "Letter", or "gc=Letter"; take last.
                let nm = name.rsplit('=').next().unwrap_or(&name).trim().to_string();
                if !valid_prop(&nm) { return Err(()); }
                Ok(single_pred(ClassPred::Prop(nm, neg)))
            }
            c if !c.is_alphanumeric() => Ok(Ast::Char(c, flags.i)),
            _ => Err(()),
        }
    }

    fn parse_class(&mut self, ci: bool) -> PResult<ClassDef> {
        let mut negated = false;
        if self.peek() == Some('^') {
            negated = true;
            self.pos += 1;
        }
        let mut items: Vec<ClassItem> = Vec::new();
        let mut first = true;
        loop {
            let c = self.next().ok_or(())?;
            if c == ']' && !first {
                break;
            }
            if c == ']' && first {
                // ']' as the first character is a literal member.
                // It may still be the start of a range below.
                // Push it and let the following logic handle ranges by
                // treating it as a plain char item for now.
                // To support ranges beginning with ']', we process it as
                // a char below, so do not push twice.
                // Fall through with c=']' as start char.
                // (handled by start-char path)
                let start = ']';
                if self.peek() == Some('-') && self.peek2().map(|x| x != ']').unwrap_or(false) {
                    self.pos += 1; // '-'
                    let end = self.class_char()?;
                    let (a, b) = match (start, end) {
                        (ClassItem::Ch(a), ClassItem::Ch(b)) => (a, b),
                        _ => return Err(()),
                    };
                    if a > b { return Err(()); }
                    items.push(ClassItem::Range(a, b));
                } else {
                    items.push(ClassItem::Ch(start));
                }
                first = false;
                continue;
            }
            first = false;
            // POSIX class [:alpha:]
            if c == '[' && self.peek() == Some(':') {
                // Could be a POSIX class; try to parse it.
                let save = self.pos;
                self.pos += 1; // ':'
                let mut neg = false;
                if self.peek() == Some('^') { neg = true; self.pos += 1; }
                let mut name = String::new();
                let mut ok = false;
                while let Some(ch) = self.next() {
                    if ch == ':' {
                        if self.eat(']') { ok = true; }
                        break;
                    }
                    name.push(ch);
                }
                if ok {
                    const NAMES: &[&str] = &["alpha","digit","alnum","space","upper","lower","xdigit","punct","cntrl","blank","print","graph","ascii","word"];
                    if let Some(found) = NAMES.iter().find(|n| **n == name) {
                        items.push(ClassItem::Posix(found, neg));
                        continue;
                    } else {
                        return Err(());
                    }
                } else {
                    self.pos = save;
                    // treat '[' literally below by handling as start char
                    // We have consumed '[', so process range/etc.
                    let start_item = ClassItem::Ch('[');
                    if self.peek() == Some('-') && self.peek2().map(|x| x != ']').unwrap_or(false) {
                        self.pos += 1;
                        let end = self.class_char()?;
                        if let (ClassItem::Ch(a), ClassItem::Ch(b)) = (start_item, end) {
                            if a > b { return Err(()); }
                            items.push(ClassItem::Range(a, b));
                            continue;
                        } else { return Err(()); }
                    }
                    items.push(start_item);
                    continue;
                }
            }
            if c == '[' {
                // A nested character class in Rust regex; parse recursively.
                // If it turns out to be unsupported, a literal '[' is the
                // safer common behaviour for simple expressions.
                let save = self.pos;
                match self.parse_class(ci) {
                    Ok(nested) => {
                        items.push(ClassItem::Nested(nested));
                        continue;
                    }
                    Err(_) => {
                        self.pos = save;
                        items.push(ClassItem::Ch('['));
                        continue;
                    }
                }
            }
            // Read a class starting element (char / escape / pred).
            let start_item = if c == '\\' {
                match self.class_escape_as_item()? {
                    Some(it) => it,
                    None => {
                        // It was a char-producing escape (represented as Ch)
                        unreachable!()
                    }
                }
            } else {
                ClassItem::Ch(c)
            };
            // Possible range: '-' with a following char that is not ']'.
            if self.peek() == Some('-') {
                if let Some(after_dash) = self.peek2() {
                    if after_dash != ']' {
                        // Range.
                        if let ClassItem::Ch(a) = start_item {
                            self.pos += 1; // '-'
                            let end_item = self.class_char()?;
                            if let ClassItem::Ch(b) = end_item {
                                if a > b { return Err(()); }
                                items.push(ClassItem::Range(a, b));
                                continue;
                            } else {
                                return Err(());
                            }
                        } else {
                            return Err(());
                        }
                    }
                }
            }
            items.push(start_item);
            let _ = ci;
        }
        Ok(ClassDef { negated, items })
    }

    fn class_char(&mut self) -> PResult<ClassItem> {
        let c = self.next().ok_or(())?;
        if c == '\\' {
            self.class_escape_as_item()
                .map(|o| o.ok_or(()))?
                .map_err(|_| ())
                .and_then(|r| r)
        } else {
            Ok(ClassItem::Ch(c))
        }
    }

    // Returns Some(item) always on success in this implementation; char
    // escapes are converted to Ch items.
    fn class_escape_as_item(&mut self) -> PResult<Option<ClassItem>> {
        let c = self.next().ok_or(())?;
        let item = match c {
            'd' => ClassItem::Pred(ClassPred::Digit(false)),
            'D' => ClassItem::Pred(ClassPred::Digit(true)),
            'w' => ClassItem::Pred(ClassPred::Word(false)),
            'W' => ClassItem::Pred(ClassPred::Word(true)),
            's' => ClassItem::Pred(ClassPred::Space(false)),
            'S' => ClassItem::Pred(ClassPred::Space(true)),
            'n' => ClassItem::Ch('\n'),
            'r' => ClassItem::Ch('\r'),
            't' => ClassItem::Ch('\t'),
            'f' => ClassItem::Ch('\u{c}'),
            'v' => ClassItem::Ch('\u{b}'),
            'a' => ClassItem::Ch('\u{7}'),
            'b' => ClassItem::Ch('\u{8}'),
            'x' => {
                if self.eat('{') {
                    let mut s = String::new();
                    while let Some(ch) = self.next() {
                        if ch == '}' { break; }
                        s.push(ch);
                    }
                    let v = u32::from_str_radix(&s, 16).map_err(|_| ())?;
                    ClassItem::Ch(char::from_u32(v).ok_or(())?)
                } else {
                    let h1 = self.next().ok_or(())?;
                    let h2 = self.next().ok_or(())?;
                    if !h1.is_ascii_hexdigit() || !h2.is_ascii_hexdigit() { return Err(()); }
                    let v = u32::from_str_radix(&format!("{}{}", h1, h2), 16).map_err(|_| ())?;
                    ClassItem::Ch(char::from_u32(v).ok_or(())?)
                }
            }
            'u' => {
                if self.eat('{') {
                    let mut s = String::new();
                    while let Some(ch) = self.next() {
                        if ch == '}' { break; }
                        s.push(ch);
                    }
                    let v = u32::from_str_radix(&s, 16).map_err(|_| ())?;
                    ClassItem::Ch(char::from_u32(v).ok_or(())?)
                } else {
                    let mut s = String::new();
                    for _ in 0..4 {
                        let h = self.next().ok_or(())?;
                        if !h.is_ascii_hexdigit() { return Err(()); }
                        s.push(h);
                    }
                    let v = u32::from_str_radix(&s, 16).map_err(|_| ())?;
                    ClassItem::Ch(char::from_u32(v).ok_or(())?)
                }
            }
            'p' | 'P' => {
                let neg = c == 'P';
                let name = if self.eat('{') {
                    let mut s = String::new();
                    while let Some(ch) = self.next() {
                        if ch == '}' { break; }
                        s.push(ch);
                    }
                    s
                } else {
                    self.next().ok_or(())?.to_string()
                };
                let nm = name.rsplit('=').next().unwrap_or(&name).trim().to_string();
                if !valid_prop(&nm) { return Err(()); }
                ClassItem::Pred(ClassPred::Prop(nm, neg))
            }
            c if !c.is_alphanumeric() => ClassItem::Ch(c),
            _ => return Err(()),
        };
        Ok(Some(item))
    }
}

fn single_pred(p: ClassPred) -> Ast {
    Ast::Class(ClassDef { negated: false, items: vec![ClassItem::Pred(p)] }, false)
}

impl Regex {
    pub fn new(pattern: &str) -> Result<Regex, ()> {
        let mut parser = Parser { chars: pattern.chars().collect(), pos: 0 };
        let flags = Flags::default();
        let ast = parser.parse_alt(flags)?;
        parser.skip_x(flags);
        if parser.pos != parser.chars.len() {
            return Err(());
        }
        Ok(Regex { ast, pattern: pattern.to_string() })
    }

    pub fn as_str(&self) -> &str {
        &self.pattern
    }

    pub fn is_match(&self, text: &str) -> bool {
        self.find(text).is_some()
    }

    pub fn find(&self, text: &str) -> Option<(usize, usize)> {
        let chars: Vec<char> = text.chars().collect();
        self.find_in_chars(&chars, 0)
    }

    fn find_in_chars(&self, chars: &[char], from: usize) -> Option<(usize, usize)> {
        let mut start = from;
        loop {
            if start > chars.len() {
                return None;
            }
            let mut matcher = Matcher { text: chars, steps: 0 };
            let mut result: Option<usize> = None;
            let start_pos = start;
            let ok = matcher.match_node(&self.ast, start_pos, &mut |_m, end| {
                result = Some(end);
                true
            });
            if ok {
                if let Some(end) = result {
                    return Some((char_idx_to_byte(chars, start), char_idx_to_byte(chars, end)));
                }
            }
            start += 1;
        }
    }

    pub fn find_iter<'a>(&self, text: &'a str) -> Vec<(usize, usize)> {
        let chars: Vec<char> = text.chars().collect();
        let mut out = Vec::new();
        let mut pos = 0usize; // char index
        while pos <= chars.len() {
            let found = self.find_in_chars(&chars, pos);
            let Some((bs, be)) = found else { break };
            let s = byte_to_char_idx(&chars, bs);
            let e = byte_to_char_idx(&chars, be);
            out.push((bs, be));
            if e == s {
                pos = e + 1;
            } else {
                pos = e;
            }
            if out.len() > 10000 {
                break;
            }
        }
        out
    }
}

fn char_idx_to_byte(chars: &[char], idx: usize) -> usize {
    chars.iter().take(idx).map(|c| c.len_utf8()).sum()
}
fn byte_to_char_idx(chars: &[char], byte: usize) -> usize {
    let mut b = 0usize;
    for (i, c) in chars.iter().enumerate() {
        if b >= byte {
            return i;
        }
        b += c.len_utf8();
    }
    chars.len()
}

/// Escape a literal string using the same meta-character set as the
/// `regex` crate's `escape` helper.
pub fn escape_literal(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        if matches!(c, '\\' | '.' | '+' | '*' | '?' | '(' | ')' | '|' | '[' | ']' | '{' | '}' | '^' | '$' | '#' | '&' | '-' | '~') {
            out.push('\\');
        }
        out.push(c);
    }
    out
}

struct Matcher<'a> {
    text: &'a [char],
    steps: usize,
}

impl<'a> Matcher<'a> {
    fn match_node(
        &mut self,
        node: &Ast,
        pos: usize,
        cont: &mut dyn FnMut(&mut Self, usize) -> bool,
    ) -> bool {
        self.steps += 1;
        if self.steps > 2_000_000 {
            return false;
        }
        match node {
            Ast::Empty => cont(self, pos),
            Ast::Char(want, ci) => {
                if pos < self.text.len() && chars_eq(*want, self.text[pos], *ci) {
                    cont(self, pos + 1)
                } else {
                    false
                }
            }
            Ast::Any(not_newline) => {
                if pos < self.text.len() && (!*not_newline || self.text[pos] != '\n') {
                    // `not_newline` is stored as "dot does NOT match newline"
                    // via the `s` flag inversion in the parser: Any(false)
                    // comes from '.' without (?s); Any(true) with (?s).
                    cont(self, pos + 1)
                } else {
                    false
                }
            }
            Ast::Class(class, ci) => {
                if pos < self.text.len() && class.matches(self.text[pos], *ci) {
                    cont(self, pos + 1)
                } else {
                    false
                }
            }
            Ast::StartText => {
                if pos == 0 { cont(self, pos) } else { false }
            }
            Ast::EndText => {
                if pos == self.text.len() { cont(self, pos) } else { false }
            }
            Ast::StartLine => {
                if pos == 0 || self.text[pos - 1] == '\n' { cont(self, pos) } else { false }
            }
            Ast::EndLine => {
                if pos == self.text.len() || self.text[pos] == '\n' { cont(self, pos) } else { false }
            }
            Ast::WordBoundary(want) => {
                let before = if pos == 0 { false } else { is_word_char(self.text[pos - 1]) };
                let after = if pos >= self.text.len() { false } else { is_word_char(self.text[pos]) };
                if (before != after) == *want { cont(self, pos) } else { false }
            }
            Ast::Group(inner) => self.match_node(inner, pos, cont),
            Ast::Seq(items) => self.match_seq(items, 0, pos, cont),
            Ast::Alt(branches) => {
                for b in branches {
                    if self.match_node(b, pos, cont) {
                        return true;
                    }
                }
                false
            }
            Ast::Repeat { node: inner, min, max, lazy } => {
                self.match_repeat(inner, *min, *max, *lazy, 0, pos, cont)
            }
        }
    }

    fn match_seq(
        &mut self,
        items: &[Ast],
        idx: usize,
        pos: usize,
        cont: &mut dyn FnMut(&mut Self, usize) -> bool,
    ) -> bool {
        if idx >= items.len() {
            return cont(self, pos);
        }
        self.match_node(&items[idx], pos, &mut |m, next| {
            m.match_seq(items, idx + 1, next, cont)
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn match_repeat(
        &mut self,
        inner: &Ast,
        min: u32,
        max: Option<u32>,
        lazy: bool,
        count: u32,
        pos: usize,
        cont: &mut dyn FnMut(&mut Self, usize) -> bool,
    ) -> bool {
        self.steps += 1;
        if self.steps > 2_000_000 {
            return false;
        }
        let can_more = max.map(|mx| count < mx).unwrap_or(true);
        if count < min {
            if !can_more {
                return false;
            }
            // Must consume one more.
            return self.match_node(inner, pos, &mut |m, next| {
                if next == pos {
                    // An empty iteration: count it, but avoid an unbounded
                    // loop once the minimum is satisfied below by letting
                    // the recursive call handle it; the step guard and the
                    // count bound keep this terminating.
                    if count + 1 >= min {
                        cont(m, next)
                    } else {
                        m.match_repeat(inner, min, max, lazy, count + 1, next, cont)
                    }
                } else {
                    m.match_repeat(inner, min, max, lazy, count + 1, next, cont)
                }
            });
        }
        if lazy {
            if cont(self, pos) {
                return true;
            }
            if can_more {
                return self.match_node(inner, pos, &mut |m, next| {
                    if next == pos {
                        false
                    } else {
                        m.match_repeat(inner, min, max, lazy, count + 1, next, cont)
                    }
                });
            }
            false
        } else {
            if can_more {
                let more = self.match_node(inner, pos, &mut |m, next| {
                    if next == pos {
                        false
                    } else {
                        m.match_repeat(inner, min, max, lazy, count + 1, next, cont)
                    }
                });
                if more {
                    return true;
                }
            }
            cont(self, pos)
        }
    }
}
