}

const TCSANOW: i32 = 0;
const TIOCGWINSZ: u64 = 0x5413;
const POLLIN: i16 = 1;
const SIGWINCH: i32 = 28;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum KeyCode {
    Char(char),
    Left,
    Right,
    Up,
    Down,
    Home,
    End,
    PageUp,
    PageDown,
    Backspace,
    Delete,
    Insert,
    Tab,
    BackTab,
    Esc,
    Enter,
    Null,
    Other,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct KeyEvent {
    pub code: KeyCode,
    pub ctrl: bool,
    pub alt: bool,
    pub shift: bool,
}

impl KeyEvent {
    pub fn simple(code: KeyCode) -> Self {
        KeyEvent { code, ctrl: false, alt: false, shift: false }
    }
}

#[derive(Clone, Debug)]
pub enum Event {
    Key(KeyEvent),
    Resize,
    Other,
}

pub struct Terminal {
    input_fd: i32,
    close_input: bool,
    original: Option<Termios>,
}

impl Terminal {
    pub fn new() -> io::Result<Terminal> {
        let mut close_input = false;
        let input_fd = if unsafe { isatty(0) } == 1 {
            0
        } else {
            let path = b"/dev/tty\0";
            let fd = unsafe { open(path.as_ptr(), 2) }; // O_RDWR
            if fd >= 0 {
                close_input = true;
                fd
            } else if unsafe { isatty(1) } == 1 {
                1
            } else if unsafe { isatty(2) } == 1 {
                2
            } else {
                return Err(io::Error::last_os_error());
            }
        };

        let mut term = Termios {
            c_iflag: 0,
            c_oflag: 0,
            c_cflag: 0,
            c_lflag: 0,
            c_line: 0,
            c_cc: [0; 32],
            c_ispeed: 0,
            c_ospeed: 0,
        };
        if unsafe { tcgetattr(input_fd, &mut term) } != 0 {
            let e = io::Error::last_os_error();
            if close_input {
                unsafe { close(input_fd) };
            }
            return Err(e);
        }
        let original = term;
        let mut raw = term;
        unsafe {
            cfmakeraw(&mut raw);
            if tcsetattr(input_fd, TCSANOW, &raw) != 0 {
                let e = io::Error::last_os_error();
                if close_input {
                    close(input_fd);
                }
                return Err(e);
            }
            signal(SIGWINCH, on_winch as usize);
        }
        let mut t = Terminal { input_fd, close_input, original: Some(original) };
        t.write_str("\x1b[?1049h\x1b[?25l\x1b[2J\x1b[H")?;
        Ok(t)
    }

    pub fn restore(&mut self) {
        let _ = self.write_str("\x1b[?25h\x1b[?1049l");
        if let Some(orig) = self.original.take() {
            unsafe {
                tcsetattr(self.input_fd, TCSANOW, &orig);
            }
        }
        if self.close_input {
            unsafe { close(self.input_fd) };
            self.close_input = false;
        }
    }

    pub fn size(&self) -> (u16, u16) {
        for fd in [1, self.input_fd, 0, 2] {
            let mut ws = Winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
            if unsafe { ioctl(fd, TIOCGWINSZ, &mut ws as *mut Winsize) } == 0 {
                if ws.ws_col > 0 && ws.ws_row > 0 {
                    return (ws.ws_col, ws.ws_row);
                }
            }
        }
        let cols = std::env::var("COLUMNS").ok().and_then(|v| v.parse().ok()).unwrap_or(80);
        let rows = std::env::var("LINES").ok().and_then(|v| v.parse().ok()).unwrap_or(24);
        (cols, rows)
    }

    pub fn write_str(&mut self, s: &str) -> io::Result<()> {
        let mut out = io::stdout().lock();
        out.write_all(s.as_bytes())?;
        out.flush()
    }

    pub fn reader(&self) -> EventReader {
        EventReader { fd: self.input_fd, pending: Vec::new(), queue: VecDeque::new() }
    }
}

impl Drop for Terminal {
    fn drop(&mut self) {
        // If we are unwinding, still make a best effort to leave the user's
        // terminal in a usable state.
        if self.original.is_some() {
            self.restore();
        }
    }
}

pub struct EventReader {
    fd: i32,
    pending: Vec<u8>,
    queue: VecDeque<Event>,
}

enum Parse {
    Event(Event, usize),
    Ignored(usize),
    NeedMore,
}

impl EventReader {
    pub fn next_event(&mut self) -> io::Result<Option<Event>> {
        loop {
            if let Some(e) = self.queue.pop_front() {
                return Ok(Some(e));
            }
            // Try to parse anything already buffered.
            loop {
                match parse_input(&self.pending) {
                    Parse::Event(e, n) => {
                        self.pending.drain(..n);
                        self.queue.push_back(e);
                        break;
                    }
                    Parse::Ignored(n) => {
                        self.pending.drain(..n);
                        continue;
                    }
                    Parse::NeedMore => break,
                }
            }
            if !self.queue.is_empty() {
                continue;
            }
            let incomplete_escape = !self.pending.is_empty();
            let mut pfd = PollFd { fd: self.fd, events: POLLIN, revents: 0 };
            let timeout = if incomplete_escape { 10 } else { -1 };
            let r = unsafe { poll(&mut pfd, 1, timeout) };
            if r < 0 {
                let e = io::Error::last_os_error();
                if e.raw_os_error() == Some(4) {
                    // EINTR
                    if GOT_WINCH.swap(false, Ordering::SeqCst) {
                        return Ok(Some(Event::Resize));
                    }
                    continue;
                }
                return Err(e);
            }
            if r == 0 {
                // A timeout while an escape sequence is incomplete: flush it.
                if self.pending.len() == 1 && self.pending[0] == 0x1b {
                    self.pending.clear();
                    return Ok(Some(Event::Key(KeyEvent::simple(KeyCode::Esc))));
                }
                if !self.pending.is_empty() {
                    // Drop an unrecognised partial sequence.
                    self.pending.clear();
                    continue;
                }
                continue;
            }
            if GOT_WINCH.swap(false, Ordering::SeqCst) {
                // Still consume any pending input first on the next call;
                // reporting the resize promptly is visually equivalent.
                return Ok(Some(Event::Resize));
            }
            let mut buf = [0u8; 4096];
            let n = unsafe { read(self.fd, buf.as_mut_ptr(), buf.len()) };
            if n < 0 {
                let e = io::Error::last_os_error();
                if e.raw_os_error() == Some(4) {
                    if GOT_WINCH.swap(false, Ordering::SeqCst) {
                        return Ok(Some(Event::Resize));
                    }
                    continue;
                }
                return Err(e);
            }
            if n == 0 {
                return Ok(None);
            }
            self.pending.extend_from_slice(&buf[..n as usize]);
        }
    }
}

fn modifier_from_param(v: i32) -> (bool, bool, bool) {
    // CSI modifier parameter: 1 + (shift=1, alt=2, ctrl=4)
    let m = v.saturating_sub(1);
    (m & 2 != 0, m & 1 != 0, m & 4 != 0) // (shift, alt, ctrl) as (shift, alt, ctrl) unpacked by caller
}

fn parse_input(data: &[u8]) -> Parse {
    if data.is_empty() {
        return Parse::NeedMore;
    }
    let b = data[0];
    match b {
        0x1b => parse_escape(data),
        0x7f => Parse::Event(Event::Key(KeyEvent::simple(KeyCode::Backspace)), 1),
        0x08 => Parse::Event(
            Event::Key(KeyEvent { code: KeyCode::Char('h'), ctrl: true, alt: false, shift: false }),
            1,
        ),
        0x09 => Parse::Event(Event::Key(KeyEvent::simple(KeyCode::Tab)), 1),
        0x0d => Parse::Event(Event::Key(KeyEvent::simple(KeyCode::Enter)), 1),
        0x0a => Parse::Event(
            Event::Key(KeyEvent { code: KeyCode::Char('j'), ctrl: true, alt: false, shift: false }),
            1,
        ),
        0x01..=0x1a => {
            let c = (b'a' + (b - 1)) as char;
            Parse::Event(
                Event::Key(KeyEvent { code: KeyCode::Char(c), ctrl: true, alt: false, shift: false }),
                1,
            )
        }
        0x00..=0x1f => Parse::Ignored(1),
        _ => {
            // UTF-8 character.
            let need = utf8_len(b);
            if need == 0 {
                return Parse::Ignored(1);
            }
            if data.len() < need {
                // Check that the bytes so far could be a prefix.
                if data.iter().skip(1).all(|x| (0x80..0xc0).contains(x)) {
                    return Parse::NeedMore;
                }
                return Parse::Ignored(1);
            }
            match std::str::from_utf8(&data[..need]) {
                Ok(s) => {
                    let c = s.chars().next().unwrap_or(' ');
                    Parse::Event(
                        Event::Key(KeyEvent {
                            code: KeyCode::Char(c),
                            ctrl: false,
                            alt: false,
                            shift: c.is_uppercase(),
                        }),
                        need,
                    )
                }
                Err(_) => Parse::Ignored(1),
            }
        }
    }
}

fn utf8_len(b: u8) -> usize {
    if b < 0x80 {
        1
    } else if (0xc2..0xe0).contains(&b) {
        2
    } else if (0xe0..0xf0).contains(&b) {
        3
    } else if (0xf0..0xf5).contains(&b) {
        4
    } else {
        0
    }
}

fn parse_escape(data: &[u8]) -> Parse {
    if data.len() == 1 {
        return Parse::NeedMore;
    }
    match data[1] {
        b'[' => {
            // CSI: find the final byte.
            let mut end = None;
            for (i, &x) in data.iter().enumerate().skip(2) {
                if (0x40..=0x7e).contains(&x) {
                    end = Some(i);
                    break;
                }
                if i > 40 {
                    break;
                }
            }
            let Some(end) = end else {
                if data.len() > 48 {
                    return Parse::Ignored(data.len());
                }
                return Parse::NeedMore;
            };
            let finalb = data[end];
            let params = &data[2..end];
            let ev = parse_csi(params, finalb);
            match ev {
                Some(e) => Parse::Event(e, end + 1),
                None => Parse::Ignored(end + 1),
            }
        }
        b'O' => {
            if data.len() < 3 {
                return Parse::NeedMore;
            }
            let code = match data[2] {
                b'A' => KeyCode::Up,
                b'B' => KeyCode::Down,
                b'C' => KeyCode::Right,
                b'D' => KeyCode::Left,
                b'H' => KeyCode::Home,
                b'F' => KeyCode::End,
                _ => return Parse::Ignored(3),
            };
            Parse::Event(Event::Key(KeyEvent::simple(code)), 3)
        }
        0x1b => Parse::Event(Event::Key(KeyEvent::simple(KeyCode::Esc)), 1),
        0x7f => Parse::Event(
            Event::Key(KeyEvent { code: KeyCode::Backspace, ctrl: false, alt: true, shift: false }),
            2,
        ),
        b'\t' => Parse::Event(
            Event::Key(KeyEvent { code: KeyCode::Tab, ctrl: false, alt: true, shift: false }),
            2,
        ),
        b'\r' => Parse::Event(
            Event::Key(KeyEvent { code: KeyCode::Enter, ctrl: false, alt: true, shift: false }),
            2,
        ),
        _ => {
            // Alt + character (or an unrecognised control sequence).
            let need = utf8_len(data[1]);
            if need == 0 {
                return Parse::Ignored(2.min(data.len()));
            }
            if data.len() < 1 + need {
                return Parse::NeedMore;
            }
            match std::str::from_utf8(&data[1..1 + need]) {
                Ok(s) => {
                    let c = s.chars().next().unwrap_or(' ');
                    Parse::Event(
                        Event::Key(KeyEvent {
                            code: KeyCode::Char(c),
                            ctrl: false,
                            alt: true,
                            shift: c.is_uppercase(),
                        }),
                        1 + need,
                    )
                }
                Err(_) => Parse::Ignored(2),
            }
        }
    }
}

fn parse_csi(params: &[u8], finalb: u8) -> Option<Event> {
    if params.first() == Some(&b'<') {
        return Some(Event::Other); // mouse
    }
    if params.first() == Some(&b'?') {
        return Some(Event::Other);
    }
    let txt = std::str::from_utf8(params).unwrap_or("");
    let mut parts = txt.split(';');
    let first: i32 = parts.next().and_then(|v| v.parse().ok()).unwrap_or(1);
    let second: i32 = parts.next().and_then(|v| v.parse().ok()).unwrap_or(1);
    let (shift, alt, ctrl) = {
        let (s, a, c) = modifier_from_param(second);
        (a, s, c) // store as (shift, alt, ctrl) below via named fields
    };
    // modifier_from_param returns (shiftish, altish, ctrl) reordered above;
    // decode directly to avoid confusion:
    let m = second.saturating_sub(1);
    let shift = m & 1 != 0;
    let alt = m & 2 != 0;
    let ctrl = m & 4 != 0;
    let _ = (shift, alt, ctrl, txt);
    let key = |code: KeyCode| {
        Event::Key(KeyEvent { code, ctrl, alt, shift })
    };
    match finalb {
        b'A' => Some(key(KeyCode::Up)),
        b'B' => Some(key(KeyCode::Down)),
        b'C' => Some(key(KeyCode::Right)),
        b'D' => Some(key(KeyCode::Left)),
        b'H' => Some(key(KeyCode::Home)),
        b'F' => Some(key(KeyCode::End)),
        b'Z' => Some(Event::Key(KeyEvent { code: KeyCode::BackTab, ctrl, alt, shift: true })),
        b'~' => match first {
            1 | 7 => Some(key(KeyCode::Home)),
            4 | 8 => Some(key(KeyCode::End)),
            2 => Some(key(KeyCode::Insert)),
            3 => Some(key(KeyCode::Delete)),
            5 => Some(key(KeyCode::PageUp)),
            6 => Some(key(KeyCode::PageDown)),
            15 => Some(Event::Other),
            _ => Some(Event::Other),
        },
        b'u' => {
            // Kitty keyboard protocol: codepoint ; modifiers u
            if first > 0 {
                if let Some(c) = char::from_u32(first as u32) {
                    return Some(Event::Key(KeyEvent { code: KeyCode::Char(c), ctrl, alt, shift }));
                }
            }
            Some(Event::Other)
        }
        b'M' | b'm' => Some(Event::Other),
        _ => Some(Event::Other),
    }
}
