fn parse_input(data: &[u8]) -> Parse {
    if data.is_empty() {
        return Parse::NeedMore;
    }
    let b = data[0];
    match b {
        0x1b => parse_escape(data),
        0x7f => Parse::Event(Event::Key(KeyEvent::simple(KeyCode::Backspace)), 1),
