                // Check that the bytes so far could be a prefix.
                if data.iter().skip(1).all(|x| (0x80..0xc0).contains(x)) {
                    return Parse::NeedMore;
                }
                return Parse::Ignored(1);
            }
            match std::str::from_utf8(&data[..need]) {
                Ok(s) => {
                    let c = s.chars().next().unwrap_or(' ');
