                    end = Some(i);
                    break;
                }
                if i > 40 {
                    break;
                }
            }
            let Some(end) = end else {
                if data.len() > 48 {
                    return Parse::Ignored(data.len());
                }
                return Parse::NeedMore;
            };
            let finalb = data[end];
            let params = &data[2..end];
            let ev = parse_csi(params, finalb);
            match ev {
                Some(e) => Parse::Event(e, end + 1),
                None => Parse::Ignored(end + 1),
            }
        }
        b'O' => {
            if data.len() < 3 {
                return Parse::NeedMore;
            }
            let code = match data[2] {
                b'A' => KeyCode::Up,
                b'B' => KeyCode::Down,
                b'C' => KeyCode::Right,
                b'D' => KeyCode::Left,
                b'H' => KeyCode::Home,
                b'F' => KeyCode::End,
                _ => return Parse::Ignored(3),
            };
            Parse::Event(Event::Key(KeyEvent::simple(code)), 3)
        }
        0x1b => Parse::Event(Event::Key(KeyEvent::simple(KeyCode::Esc)), 1),
        0x7f => Parse::Event(
            Event::Key(KeyEvent { code: KeyCode::Backspace, ctrl: false, alt: true, shift: false }),
            2,
        ),
        b'\t' => Parse::Event(
            Event::Key(KeyEvent { code: KeyCode::Tab, ctrl: false, alt: true, shift: false }),
            2,
        ),
        b'\r' => Parse::Event(
            Event::Key(KeyEvent { code: KeyCode::Enter, ctrl: false, alt: true, shift: false }),
            2,
        ),
        _ => {
            // Alt + character (or an unrecognised control sequence).
            let need = utf8_len(data[1]);
            if need == 0 {
                return Parse::Ignored(2.min(data.len()));
            }
            if data.len() < 1 + need {
                return Parse::NeedMore;
            }
            match std::str::from_utf8(&data[1..1 + need]) {
                Ok(s) => {
                    let c = s.chars().next().unwrap_or(' ');
                    Parse::Event(
                        Event::Key(KeyEvent {
                            code: KeyCode::Char(c),
                            ctrl: false,
                            alt: true,
                            shift: c.is_uppercase(),
                        }),
                        1 + need,
                    )
                }
                Err(_) => Parse::Ignored(2),
            }
        }
    }
}

fn parse_csi(params: &[u8], finalb: u8) -> Option<Event> {
    if params.first() == Some(&b'<') {
        return Some(Event::Other); // mouse
    }
    if params.first() == Some(&b'?') {
        return Some(Event::Other);
    }
    let txt = std::str::from_utf8(params).unwrap_or("");
    let mut parts = txt.split(';');
    let first: i32 = parts.next().and_then(|v| v.parse().ok()).unwrap_or(1);
    let second: i32 = parts.next().and_then(|v| v.parse().ok()).unwrap_or(1);
    let (shift, alt, ctrl) = {
        let (s, a, c) = modifier_from_param(second);
        (a, s, c) // store as (shift, alt, ctrl) below via named fields
    };
    // modifier_from_param returns (shiftish, altish, ctrl) reordered above;
    // decode directly to avoid confusion:
    let m = second.saturating_sub(1);
    let shift = m & 1 != 0;
    let alt = m & 2 != 0;
    let ctrl = m & 4 != 0;
    let _ = (shift, alt, ctrl, txt);
    let key = |code: KeyCode| {
        Event::Key(KeyEvent { code, ctrl, alt, shift })
    };
    match finalb {
        b'A' => Some(key(KeyCode::Up)),
        b'B' => Some(key(KeyCode::Down)),
        b'C' => Some(key(KeyCode::Right)),
        b'D' => Some(key(KeyCode::Left)),
        b'H' => Some(key(KeyCode::Home)),
        b'F' => Some(key(KeyCode::End)),
        b'Z' => Some(Event::Key(KeyEvent { code: KeyCode::BackTab, ctrl, alt, shift: true })),
        b'~' => match first {
            1 | 7 => Some(key(KeyCode::Home)),
            4 | 8 => Some(key(KeyCode::End)),
            2 => Some(key(KeyCode::Insert)),
            3 => Some(key(KeyCode::Delete)),
            5 => Some(key(KeyCode::PageUp)),
            6 => Some(key(KeyCode::PageDown)),
            15 => Some(Event::Other),
            _ => Some(Event::Other),
        },
        b'u' => {
            // Kitty keyboard protocol: codepoint ; modifiers u
            if first > 0 {
                if let Some(c) = char::from_u32(first as u32) {
                    return Some(Event::Key(KeyEvent { code: KeyCode::Char(c), ctrl, alt, shift }));
                }
            }
            Some(Event::Other)
        }
        b'M' | b'm' => Some(Event::Other),
        _ => Some(Event::Other),
    }
}
