#[derive(Clone, Copy, PartialEq, Debug)]
enum Colour {
    Reset,
    Yellow,
    Rgb(u8, u8, u8),
}

#[derive(Clone, Copy, PartialEq, Debug)]
struct Style {
    fg: Colour,
    bg: Colour,
    bold: bool,
    reverse: bool,
}

impl Style {
    const fn plain() -> Style {
        Style { fg: Colour::Reset, bg: Colour::Reset, bold: false, reverse: false }
    }
    fn with_fg_bg(fg: Colour, bg: Colour) -> Style {
        Style { fg, bg, bold: false, reverse: false }
    }
}

#[derive(Clone, PartialEq, Debug)]
struct Cell {
    text: String,
    style: Style,
}

impl Default for Cell {
    fn default() -> Self {
        Cell { text: " ".to_string(), style: Style::plain() }
    }
}

struct Buffer {
    width: usize,
    height: usize,
    cells: Vec<Cell>,
}

impl Buffer {
    fn new(width: usize, height: usize) -> Buffer {
        Buffer { width, height, cells: vec![Cell::default(); width.saturating_mul(height)] }
    }
    fn idx(&self, x: usize, y: usize) -> Option<usize> {
        if x < self.width && y < self.height {
            Some(y * self.width + x)
        } else {
            None
        }
    }
    fn set(&mut self, x: usize, y: usize, text: &str, style: Style) {
        if let Some(i) = self.idx(x, y) {
            self.cells[i] = Cell { text: text.to_string(), style };
        }
    }
    fn fill_rect(&mut self, x: usize, y: usize, w: usize, h: usize, style: Style) {
        for yy in y..y.saturating_add(h) {
            for xx in x..x.saturating_add(w) {
                self.set(xx, yy, " ", style);
            }
        }
    }
    /// Draw a string starting at (x, y), stopping at `max_width` columns.
    /// Returns the number of columns used.
    fn draw_text(&mut self, mut x: usize, y: usize, text: &str, style: Style, max_width: usize) -> usize {
        let start_x = x;
        let limit = start_x.saturating_add(max_width);
        for g in graphemes(text) {
            if x >= limit || x >= self.width {
                break;
            }
            let w = str_width(&g);
            if w == 0 {
                // A zero-width grapheme on its own has nowhere sensible to
                // live; combining characters are kept with their base by
                // `graphemes`, so this is mostly control characters.
                continue;
            }
            if x + w > limit {
                break;
            }
            self.set(x, y, &g, style);
            if w == 2 {
                // Mark the continuation cell with the same style and no
                // symbol of its own.
                self.set(x + 1, y, "", style);
            }
            x += w;
        }
        x - start_x
    }
    fn render(&self) -> String {
        let mut out = String::new();
        let mut cur_style: Option<Style> = None;
        for y in 0..self.height {
            out.push_str(&format!("\x1b[{};1H", y + 1));
            let mut x = 0usize;
            while x < self.width {
                let cell = &self.cells[y * self.width + x];
                if cell.style != cur_style.unwrap_or(Style {
                    fg: Colour::Rgb(1, 2, 3),
                    bg: Colour::Reset,
                    bold: false,
                    reverse: false,
                }) {
                    out.push_str(&sgr(cell.style));
                    cur_style = Some(cell.style);
                }
                if cell.text.is_empty() {
                    // Continuation of a wide character; the terminal has
                    // already advanced over this column.
                    x += 1;
                    continue;
                }
                out.push_str(&cell.text);
                x += str_width(&cell.text).max(1);
            }
            out.push_str("\x1b[0m");
            cur_style = None;
        }
        out
    }
}

fn sgr(style: Style) -> String {
    let mut codes: Vec<String> = vec!["0".to_string()];
    if style.bold {
        codes.push("1".to_string());
    }
    if style.reverse {
        codes.push("7".to_string());
    }
    match style.fg {
        Colour::Reset => codes.push("39".to_string()),
        Colour::Yellow => codes.push("33".to_string()),
        Colour::Rgb(r, g, b) => codes.push(format!("38;2;{};{};{}", r, g, b)),
    }
    match style.bg {
        Colour::Reset => codes.push("49".to_string()),
        Colour::Yellow => codes.push("43".to_string()),
        Colour::Rgb(r, g, b) => codes.push(format!("48;2;{};{};{}", r, g, b)),
    }
    format!("\x1b[{}m", codes.join(";"))
}

fn is_combining(c: char) -> bool {
    matches!(c as u32,
        0x0300..=0x036f | 0x0483..=0x0489 | 0x0591..=0x05bd | 0x05bf | 0x05c1..=0x05c2
        | 0x05c4..=0x05c7 | 0x0610..=0x061a | 0x064b..=0x065f | 0x0670 | 0x06d6..=0x06dc
        | 0x06df..=0x06e4 | 0x06e7..=0x06e8 | 0x06ea..=0x06ed | 0x0e31 | 0x0e34..=0x0e3a
        | 0x0e47..=0x0e4e | 0x0eb1 | 0x0eb4..=0x0eb9 | 0x0ebb..=0x0ebc | 0x0ec8..=0x0ecd
        | 0x16af..=0x16ed | 0x18b0..=0x18f5 | 0x1ab0..=0x1b04 | 0x1b36..=0x1b3e | 0x1b80..=0x1b82
        | 0x1ba2..=0x1bad | 0x1dc0..=0x1dff | 0x1f3fb..=0x1f3ff | 0x20d0..=0x20f0
        | 0x3099..=0x309a | 0xfe00..=0xfe0f | 0xfe20..=0xfe2f | 0xe0100..=0xe01ef)
        || c == '\u{200d}'
}

fn char_width(c: char) -> usize {
    let cp = c as u32;
    if cp == 0 {
        return 0;
    }
    if cp < 32 || (0x7f..0xa0).contains(&cp) {
        return 0;
    }
    if is_combining(c) {
        return 0;
    }
    if matches!(cp,
        0x1100..=0x115f | 0x2329..=0x232a | 0x2e80..=0xa4cf | 0xac00..=0xd7a3
        | 0xf900..=0xfaff | 0xfe10..=0xfe19 | 0xfe30..=0xfe6b | 0xff00..=0xff60
        | 0xffe0..=0xffe6 | 0x1f300..=0x1f64f | 0x1f900..=0x1f9ff | 0x1f680..=0x1f6ff
        | 0x20000..=0x2fffd | 0x30000..=0x3fffd)
    {
        return 2;
    }
    1
}

fn str_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}

fn graphemes(s: &str) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    for c in s.chars() {
        if c == '\n' {
            continue;
        }
        if is_combining(c) {
            if let Some(last) = out.last_mut() {
                last.push(c);
                continue;
            }
        }
        if !out.is_empty() && out.last().map(|g: &String| g.ends_with('\u{200d}')).unwrap_or(false) {
            out.last_mut().unwrap().push(c);
            continue;
        }
        out.push(c.to_string());
    }
    if out.is_empty() && !s.is_empty() {
        // A string consisting solely of combining marks.
        out.push(s.to_string());
    }
    out
}

/// Word-wrap a single logical line to `width` columns, in the style of a
/// wrapping paragraph: words are moved whole to the next line when they do
/// not fit, very long words are split, and spaces at the start of a wrapped
/// line are dropped.
fn wrap_text(text: &str, width: usize) -> Vec<String> {
    if width == 0 {
        return vec![String::new()];
    }
    // Tokenise into alternating word / space runs (as grapheme strings).
    #[derive(Clone, Copy, PartialEq)]
    enum Kind {
        Word,
        Space,
    }
    let mut tokens: Vec<(Kind, String)> = Vec::new();
    for g in graphemes(text) {
        let is_space = g == " " || g == "\t";
        let kind = if is_space { Kind::Space } else { Kind::Word };
        if let Some((k, s)) = tokens.last_mut() {
            if *k == kind {
                s.push_str(&g);
                continue;
            }
        }
        tokens.push((kind, g));
    }

    let mut lines: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut cur_w = 0usize;
    let mut pending_space = String::new();
    let mut pending_w = 0usize;

    let push_line = |lines: &mut Vec<String>, cur: &mut String, cur_w: &mut usize| {
        lines.push(std::mem::take(cur));
        *cur_w = 0;
    };

    for (kind, tok) in tokens {
        match kind {
            Kind::Space => {
                if cur_w == 0 {
                    // Leading spaces on a line are trimmed.
                    continue;
                }
                pending_space = tok;
                pending_w = str_width(&pending_space);
            }
            Kind::Word => {
                let w = str_width(&tok);
                if cur_w > 0 && cur_w + pending_w + w > width {
                    push_line(&mut lines, &mut cur, &mut cur_w);
                    pending_space.clear();
                    pending_w = 0;
                }
                if cur_w == 0 {
                    pending_space.clear();
                    pending_w = 0;
                }
                if w > width {
                    // Split a long word across lines. First fill the
                    // current line (after any pending space).
                    let mut rest = tok;
                    if cur_w > 0 {
                        let avail = width - cur_w - pending_w;
                        if avail > 0 {
                            let (head, tail) = split_at_width(&rest, avail);
                            cur.push_str(&pending_space);
                            cur.push_str(&head);
                            rest = tail;
                        }
                        pending_space.clear();
                        pending_w = 0;
                        push_line(&mut lines, &mut cur, &mut cur_w);
                    }
                    while str_width(&rest) > width {
                        let (head, tail) = split_at_width(&rest, width);
                        lines.push(head);
                        rest = tail;
                    }
                    cur = rest;
                    cur_w = str_width(&cur);
                } else {
                    if cur_w > 0 {
                        cur.push_str(&pending_space);
                        cur_w += pending_w;
                    }
                    pending_space.clear();
                    pending_w = 0;
                    cur.push_str(&tok);
                    cur_w += w;
                }
            }
        }
    }
    // A trailing pending space is not rendered on the final line.
    lines.push(cur);
    if lines.is_empty() {
        lines.push(String::new());
    }
    lines
}

fn split_at_width(s: &str, width: usize) -> (String, String) {
    let mut used = 0usize;
    let mut head = String::new();
    let mut tail = String::new();
    for g in graphemes(s) {
        let w = str_width(&g);
        if used + w <= width && tail.is_empty() {
            head.push_str(&g);
            used += w;
