                        let (head, tail) = split_at_width(&rest, width);
                        lines.push(head);
                        rest = tail;
                    }
                    cur = rest;
                    cur_w = str_width(&cur);
                } else {
                    if cur_w > 0 {
                        cur.push_str(&pending_space);
                        cur_w += pending_w;
                    }
