fn bin_name() -> String {
    let arg0 = std::env::args_os().next();
    match arg0 {
        Some(a) => {
            let s = a.to_string_lossy().to_string();
            let base = s.rsplit('/').next().unwrap_or("").to_string();
            if base.is_empty() {
                "flamelens".to_string()
            } else {
                base
            }
        }
        None => "flamelens".to_string(),
    }
}

fn print_help() -> ! {
    let bin = bin_name();
    print!(
        "Usage: {} [OPTIONS] [FILENAME]\n\nArguments:\n  [FILENAME]  Profile data filename\n\nOptions:\n      --sorted   Whether to sort the stacks by time spent\n      --echo     Print data to stdout on exit. Useful when piping to other tools\n      --debug    Show debug info\n  -h, --help     Print help\n  -V, --version  Print version\n",
        bin
    );
    let _ = io::stdout().flush();
