#[derive(Clone, Debug)]
struct Node {
    name: String,
    colour_key: String,
    samples: u64,
    children: Vec<usize>,
    parent: Option<usize>,
    depth: usize,
}

#[derive(Clone, Debug)]
struct Record {
    frames: Vec<String>,
    count: u64,
}

fn parse_records(data: &str) -> Vec<Record> {
    let mut out = Vec::new();
    for line in data.split('\n') {
        let Some((stack, count_str)) = line.rsplit_once(' ') else {
            continue;
        };
        if stack.is_empty() {
            continue;
        }
        let Ok(count) = count_str.parse::<u64>() else {
            continue;
        };
        let frames: Vec<String> = stack.split(';').map(|s| s.to_string()).collect();
        out.push(Record { frames, count });
    }
    out
}

#[derive(Clone, Debug)]
struct TopEntry {
    name: String,
    total: u64,
    own: u64,
}

fn sort_top(entries: &mut [TopEntry], sort: TopSort) {
    match sort {
        TopSort::Total => entries.sort_by(|a, b| {
            b.total.cmp(&a.total).then_with(|| b.name.cmp(&a.name))
        }),
        TopSort::Own => entries.sort_by(|a, b| {
            b.own.cmp(&a.own).then_with(|| b.name.cmp(&a.name))
        }),
    }
}

fn build_top(records: &[Record]) -> Vec<TopEntry> {
    let mut map: HashMap<String, (u64, u64)> = HashMap::new();
    for rec in records {
        let mut seen: HashSet<&str> = HashSet::new();
        for frame in &rec.frames {
            if seen.insert(frame.as_str()) {
                let e = map.entry(frame.clone()).or_insert((0, 0));
                e.0 = e.0.wrapping_add(rec.count);
            }
        }
        if let Some(last) = rec.frames.last() {
            let e = map.entry(last.clone()).or_insert((0, 0));
            e.1 = e.1.wrapping_add(rec.count);
        }
    }
    let mut entries: Vec<TopEntry> = map
        .into_iter()
        .map(|(name, (total, own))| TopEntry { name, total, own })
        .collect();
    sort_top(&mut entries, TopSort::Own);
    entries
}

struct Tree {
    nodes: Vec<Node>,
}

impl Tree {
    fn build(records: &[Record], sorted: bool) -> Tree {
        let mut tree = Tree {
            nodes: vec![Node {
                name: String::new(),
                colour_key: "all".to_string(),
                samples: 0,
                children: Vec::new(),
                parent: None,
                depth: 0,
            }],
        };
        for rec in records {
            tree.nodes[0].samples = tree.nodes[0].samples.wrapping_add(rec.count);
            let mut current = 0usize;
            for frame in &rec.frames {
                let existing = tree.nodes[current]
                    .children
                    .iter()
                    .copied()
                    .find(|&id| tree.nodes[id].name == *frame);
                let child = if let Some(id) = existing {
                    id
                } else {
                    let colour_key = if current == 0 {
                        frame.clone()
                    } else {
                        format!("{};{}", tree.nodes[current].colour_key, frame)
                    };
                    // For nodes below the root, colour_key above started
                    // from the root child's own name; but the branch that
                    // built it from a non-root parent used the parent's key
                    // which already excludes "all".  The root's own key is
                    // only a placeholder for the root frame itself.
                    let id = tree.nodes.len();
                    let depth = tree.nodes[current].depth + 1;
                    tree.nodes.push(Node {
                        name: frame.clone(),
                        colour_key,
                        samples: 0,
                        children: Vec::new(),
                        parent: Some(current),
                        depth,
                    });
                    tree.nodes[current].children.push(id);
                    id
                };
                tree.nodes[child].samples = tree.nodes[child].samples.wrapping_add(rec.count);
                current = child;
            }
        }
        if sorted {
            tree.sort_children(0);
        }
        tree
    }

    fn sort_children(&mut self, node: usize) {
        let children: Vec<usize> = self.nodes[node].children.clone();
        for child in children {
            self.sort_children(child);
        }
        let nodes_ptr = &self.nodes as *const Vec<Node>;
        let mut kids = self.nodes[node].children.clone();
        kids.sort_by(|&a, &b| unsafe { (*nodes_ptr)[a].samples.cmp(&(*nodes_ptr)[b].samples) });
        kids.reverse();
        self.nodes[node].children = kids;
    }

    fn display_name(&self, node: usize) -> &str {
        if node == 0 {
            "all"
        } else {
            &self.nodes[node].name
        }
    }
    fn search_name(&self, node: usize) -> &str {
        if node == 0 {
            ""
        } else {
            &self.nodes[node].name
        }
    }
    fn count_matched(&self, node: usize, regex: &Regex) -> u64 {
        if regex.is_match(self.search_name(node)) {
            return self.nodes[node].samples;
        }
        let mut total = 0u64;
        for &child in &self.nodes[node].children.clone() {
            total = total.wrapping_add(self.count_matched(child, regex));
        }
        total
    }
}

#[derive(Clone, Debug)]
struct DisplayFrame {
    node: usize,
    depth: usize,
    x: usize,
    width: usize,
    exact_x: f64,
}

struct InputState {
    chars: Vec<char>,
    cursor: usize,
}

impl InputState {
    fn new() -> InputState {
        InputState { chars: Vec::new(), cursor: 0 }
    }
    fn clear(&mut self) {
        self.chars.clear();
        self.cursor = 0;
    }
    fn text(&self) -> String {
        self.chars.iter().collect()
    }
    fn insert(&mut self, c: char) {
        self.chars.insert(self.cursor, c);
        self.cursor += 1;
    }
    fn delete_prev_char(&mut self) {
        if self.cursor > 0 {
            self.cursor -= 1;
            self.chars.remove(self.cursor);
        }
    }
    fn delete_next_char(&mut self) {
        if self.cursor < self.chars.len() {
            self.chars.remove(self.cursor);
        }
    }
    fn prev_word_boundary(&self, mut pos: usize) -> usize {
        while pos > 0 && !self.chars[pos - 1].is_alphanumeric() {
            pos -= 1;
        }
        while pos > 0 && self.chars[pos - 1].is_alphanumeric() {
            pos -= 1;
        }
        pos
    }
    fn next_word_boundary(&self, mut pos: usize) -> usize {
        while pos < self.chars.len() && self.chars[pos].is_alphanumeric() {
            pos += 1;
        }
        while pos < self.chars.len() && !self.chars[pos].is_alphanumeric() {
            pos += 1;
        }
        pos
    }
    fn delete_prev_word(&mut self) {
        let start = self.prev_word_boundary(self.cursor);
        if start < self.cursor {
            self.chars.drain(start..self.cursor);
            self.cursor = start;
        }
    }
    fn delete_next_word(&mut self) {
        let end = self.next_word_boundary(self.cursor);
        if end > self.cursor {
            self.chars.drain(self.cursor..end);
        }
    }
}

fn frame_colour(colour_key: &str) -> (f64, Colour) {
    let mut hasher = DefaultHasher::new();
    colour_key.hash(&mut hasher);
    let t = hasher.finish() as f64 / u64::MAX as f64;
    let r = (205.0 + 50.0 * t) as u8;
    let g = (230.0 * t) as u8;
    let b = (55.0 * t) as u8;
    (t, Colour::Rgb(r, g, b))
}

fn dim_colour(c: Colour) -> Colour {
    match c {
        Colour::Rgb(r, g, b) => Colour::Rgb(
            (r as f64 * 0.4) as u8,
            (g as f64 * 0.4) as u8,
            (b as f64 * 0.4) as u8,
        ),
        other => other,
    }
}

fn pct(part: u64, total: u64) -> f64 {
    part as f64 / total as f64 * 100.0
}

struct App {
    label: String,
    data: String,
    echo: bool,
    debug: bool,
    tree: Tree,
    total: u64,
    top_entries: Vec<TopEntry>,
    top_sort: TopSort,
    view: View,
    selected: usize,
    flame_offset: usize,
    top_selected: usize,
    top_offset: usize,
    zoom: Option<usize>,
    search: Option<Regex>,
    matched_samples: u64,
    searching: bool,
    input: InputState,
    info: Option<String>,
    body_height: usize,
    display_frames: Vec<DisplayFrame>,
    trail: HashSet<usize>,
    timings: HashMap<String, Duration>,
    quit: bool,
}

impl App {
    fn new(args: &Args, label: String, data: String, records: &[Record]) -> App {
        let tree = Tree::build(records, args.sorted);
        let total = tree.nodes[0].samples;
        App {
            label,
            data,
            echo: args.echo,
            debug: args.debug,
            top_entries: build_top(records),
            tree,
            total,
            top_sort: TopSort::Own,
            view: View::Flame,
            selected: 0,
            flame_offset: 0,
            top_selected: 0,
            top_offset: 0,
            zoom: None,
            search: None,
            matched_samples: 0,
            searching: false,
            input: InputState::new(),
            info: None,
            body_height: 0,
            display_frames: Vec::new(),
            trail: HashSet::new(),
            timings: HashMap::new(),
            quit: false,
        }
    }

    fn reset(&mut self) {
        self.search = None;
        self.matched_samples = 0;
        self.zoom = None;
        self.selected = 0;
        self.flame_offset = 0;
        self.top_selected = 0;
        self.top_offset = 0;
        self.info = None;
    }

    fn apply_search(&mut self, pattern: &str) {
        if pattern.is_empty() {
            self.search = None;
            self.matched_samples = 0;
            return;
        }
        match Regex::new(pattern) {
            Ok(re) => {
                self.matched_samples = self.tree.count_matched(0, &re);
                self.search = Some(re);
            }
            Err(_) => {
                self.info = Some(format!("Invalid regex: {}", pattern));
            }
        }
    }

    fn search_like_selected(&mut self) {
        if self.selected == 0 {
            return;
        }
        let name = self.tree.search_name(self.selected).to_string();
        let pattern = format!("^{}$", regex_engine::escape_literal(&name));
        self.apply_search(&pattern);
    }

    fn build_display(&mut self, width: usize) {
        self.display_frames.clear();
        self.trail.clear();
        if width == 0 {
            return;
        }
        let mut frames: Vec<DisplayFrame> = Vec::new();
        if let Some(z) = self.zoom {
            // Trail from the root down to (and including) the zoomed frame.
            let mut path = Vec::new();
            let mut cur = Some(z);
            while let Some(id) = cur {
                path.push(id);
                cur = self.tree.nodes[id].parent;
            }
            path.reverse();
            for &id in &path {
                self.trail.insert(id);
                frames.push(DisplayFrame {
                    node: id,
                    depth: self.tree.nodes[id].depth,
                    x: 0,
                    width,
                    exact_x: 0.0,
                });
            }
            self.traverse_children(z, 0.0, width as f64, &mut frames);
        } else {
            self.traverse_node(0, 0.0, width as f64, &mut frames);
        }
        frames.sort_by(|a, b| {
            a.depth
                .cmp(&b.depth)
                .then_with(|| a.exact_x.partial_cmp(&b.exact_x).unwrap_or(Ordering::Equal))
        });
        self.display_frames = frames;
    }

    fn traverse_node(&self, node: usize, exact_x: f64, exact_width: f64, out: &mut Vec<DisplayFrame>) {
        let w = if exact_width.is_nan() || exact_width <= 0.0 {
            0usize
        } else {
            exact_width as usize
        };
        if w > 0 {
            out.push(DisplayFrame {
                node,
                depth: self.tree.nodes[node].depth,
                x: if exact_x.is_nan() || exact_x <= 0.0 { 0 } else { exact_x as usize },
                width: w,
                exact_x,
            });
        }
        self.traverse_children(node, exact_x, exact_width, out);
    }

    fn traverse_children(&self, node: usize, exact_x: f64, exact_width: f64, out: &mut Vec<DisplayFrame>) {
        let parent_samples = self.tree.nodes[node].samples;
        let mut child_x = exact_x;
        let children = self.tree.nodes[node].children.clone();
        for child in children {
            let cw = if parent_samples == 0 {
                0.0
            } else {
                (self.tree.nodes[child].samples as f64 / parent_samples as f64) * exact_width
            };
            self.traverse_node(child, child_x, cw, out);
            child_x += cw;
        }
    }

    fn displayed_top_indices(&self) -> (Vec<usize>, bool) {
        // Returns (indices into top_entries, filter matched nothing).
        match &self.search {
            None => ((0..self.top_entries.len()).collect(), false),
            Some(re) => {
                let filtered: Vec<usize> = self
                    .top_entries
                    .iter()
                    .enumerate()
                    .filter(|(_, e)| re.is_match(&e.name))
                    .map(|(i, _)| i)
                    .collect();
                if filtered.is_empty() {
                    ((0..self.top_entries.len()).collect(), true)
                } else {
                    (filtered, false)
                }
            }
        }
    }

    fn selected_text(&self) -> String {
        let name = self.tree.display_name(self.selected);
        let samples = self.tree.nodes[self.selected].samples;
        let mut s = format!("{} [{} samples, {:.2}% of all", name, samples, pct(samples, self.total));
        if let Some(z) = self.zoom {
            s.push_str(&format!(", {:.2}% of zoomed", pct(samples, self.tree.nodes[z].samples)));
        }
        s.push(']');
        s
    }

    fn match_text(&self) -> Option<String> {
        let re = self.search.as_ref()?;
        let mut s = format!(
            "\"{}\" [{} samples, {:.2}% of all",
            re.as_str(),
            self.matched_samples,
            pct(self.matched_samples, self.total)
        );
        if let Some(z) = self.zoom {
            s.push_str(&format!(", {:.2}% of zoomed", pct(self.matched_samples, self.tree.nodes[z].samples)));
        }
        s.push(']');
        if self.view == View::Top {
            let (_, no_match) = self.displayed_top_indices();
            if no_match {
                s.push_str(" (no match; showing all)");
            }
        }
        Some(s)
    }
}

