#[derive(Clone, Debug)]
struct Record {
    frames: Vec<String>,
    count: u64,
}

fn parse_records(data: &str) -> Vec<Record> {
    let mut out = Vec::new();
    for line in data.split('\n') {
        let Some((stack, count_str)) = line.rsplit_once(' ') else {
            continue;
        };
        if stack.is_empty() {
            continue;
        }
        let Ok(count) = count_str.parse::<u64>() else {
            continue;
        };
        let frames: Vec<String> = stack.split(';').map(|s| s.to_string()).collect();
        out.push(Record { frames, count });
    }
    out
}

#[derive(Clone, Debug)]
struct TopEntry {
    name: String,
    total: u64,
    own: u64,
}

fn sort_top(entries: &mut [TopEntry], sort: TopSort) {
    match sort {
        TopSort::Total => entries.sort_by(|a, b| {
            b.total.cmp(&a.total).then_with(|| b.name.cmp(&a.name))
        }),
        TopSort::Own => entries.sort_by(|a, b| {
            b.own.cmp(&a.own).then_with(|| b.name.cmp(&a.name))
        }),
    }
}

fn build_top(records: &[Record]) -> Vec<TopEntry> {
    let mut map: HashMap<String, (u64, u64)> = HashMap::new();
    for rec in records {
        let mut seen: HashSet<&str> = HashSet::new();
        for frame in &rec.frames {
            if seen.insert(frame.as_str()) {
                let e = map.entry(frame.clone()).or_insert((0, 0));
                e.0 = e.0.wrapping_add(rec.count);
            }
        }
        if let Some(last) = rec.frames.last() {
            let e = map.entry(last.clone()).or_insert((0, 0));
            e.1 = e.1.wrapping_add(rec.count);
        }
    }
    let mut entries: Vec<TopEntry> = map
        .into_iter()
        .map(|(name, (total, own))| TopEntry { name, total, own })
        .collect();
    sort_top(&mut entries, TopSort::Own);
    entries
}

struct Tree {
    nodes: Vec<Node>,
}

impl Tree {
    fn build(records: &[Record], sorted: bool) -> Tree {
        let mut tree = Tree {
            nodes: vec![Node {
                name: String::new(),
                colour_key: "all".to_string(),
                samples: 0,
                children: Vec::new(),
                parent: None,
                depth: 0,
            }],
        };
        for rec in records {
            tree.nodes[0].samples = tree.nodes[0].samples.wrapping_add(rec.count);
            let mut current = 0usize;
            for frame in &rec.frames {
                let existing = tree.nodes[current]
                    .children
                    .iter()
                    .copied()
                    .find(|&id| tree.nodes[id].name == *frame);
                let child = if let Some(id) = existing {
                    id
                } else {
                    let colour_key = if current == 0 {
                        frame.clone()
                    } else {
                        format!("{};{}", tree.nodes[current].colour_key, frame)
                    };
                    // For nodes below the root, colour_key above started
                    // from the root child's own name; but the branch that
                    // built it from a non-root parent used the parent's key
                    // which already excludes "all".  The root's own key is
                    // only a placeholder for the root frame itself.
                    let id = tree.nodes.len();
                    let depth = tree.nodes[current].depth + 1;
                    tree.nodes.push(Node {
                        name: frame.clone(),
                        colour_key,
                        samples: 0,
                        children: Vec::new(),
                        parent: Some(current),
                        depth,
                    });
                    tree.nodes[current].children.push(id);
                    id
                };
                tree.nodes[child].samples = tree.nodes[child].samples.wrapping_add(rec.count);
                current = child;
            }
        }
        if sorted {
            tree.sort_children(0);
        }
        tree
    }

    fn sort_children(&mut self, node: usize) {
        let children: Vec<usize> = self.nodes[node].children.clone();
        for child in children {
            self.sort_children(child);
        }
        let nodes_ptr = &self.nodes as *const Vec<Node>;
        let mut kids = self.nodes[node].children.clone();
        kids.sort_by(|&a, &b| unsafe { (*nodes_ptr)[a].samples.cmp(&(*nodes_ptr)[b].samples) });
        kids.reverse();
        self.nodes[node].children = kids;
    }

    fn display_name(&self, node: usize) -> &str {
        if node == 0 {
            "all"
        } else {
            &self.nodes[node].name
        }
    }
    fn search_name(&self, node: usize) -> &str {
        if node == 0 {
            ""
        } else {
            &self.nodes[node].name
        }
    }
    fn count_matched(&self, node: usize, regex: &Regex) -> u64 {
        if regex.is_match(self.search_name(node)) {
            return self.nodes[node].samples;
        }
        let mut total = 0u64;
        for &child in &self.nodes[node].children.clone() {
            total = total.wrapping_add(self.count_matched(child, regex));
        }
        total
    }
}

