fn layout(height: usize, panel_heights: &[usize]) -> (usize, usize, usize, usize) {
    // (header, body, separator shown, help shown) -- panel heights are used
    // by the caller as a total.
    let panels: usize = panel_heights.iter().sum();
    if 3 + panels + 2 <= height {
        return (3, height - (3 + panels + 2), 1, 1);
    }
    let mut header = 3usize;
    let mut sep = 1usize;
    let mut help = 1usize;
    while header + panels + sep + help > height && header > 0 {
        header -= 1;
    }
    while header + panels + sep + help > height && help > 0 {
        help -= 1;
    }
    while header + panels + sep + help > height && sep > 0 {
        sep -= 1;
    }
    (header, 0, sep, help)
}

fn percent_string(value: u64, total: u64) -> String {
    format!("{} ({:.2}%)", value, pct(value, total))
}

impl App {
    fn run(&mut self, terminal: &mut Terminal) -> io::Result<()> {
        let mut reader = terminal.reader();
        self.draw(terminal)?;
        loop {
            let Some(event) = reader.next_event()? else {
                break;
            };
            match event {
                Event::Key(key) => {
                    let started = Instant::now();
                    self.handle_key(key);
                    self.timings.insert("handle_key_events".to_string(), started.elapsed());
                    if self.quit {
                        break;
                    }
                    self.draw(terminal)?;
                }
                Event::Resize => {
                    self.draw(terminal)?;
                }
                Event::Other => {
                    self.draw(terminal)?;
                }
            }
        }
        Ok(())
    }

    fn draw(&mut self, terminal: &mut Terminal) -> io::Result<()> {
        let (tw, th) = terminal.size();
        let width = tw as usize;
        let height = th as usize;

        let started = Instant::now();
        self.build_display(width);
        self.timings.insert("flamegraph".to_string(), started.elapsed());
        if !self.timings.contains_key("render") {
            self.timings.insert("render".to_string(), started.elapsed());
        }

        // Assemble the bottom panels.
        let mut panels: Vec<(String, String)> = Vec::new();
        if self.searching {
            panels.push(("Search".to_string(), self.input.text()));
        } else {
            if let Some(m) = self.match_text() {
                panels.push(("Match".to_string(), m));
            }
            if self.view == View::Flame {
                panels.push(("Selected".to_string(), self.selected_text()));
            }
            if self.debug {
                let mut parts: Vec<String> = self
                    .timings
                    .iter()
                    .map(|(k, v)| format!("{}:{:.2}ms", k, v.as_secs_f64() * 1000.0))
                    .collect();
                parts.sort_by(|a, b| a.len().cmp(&b.len())); // placeholder, reverted below
                // The timings are stored in a hash map; rendering uses the
                // map's own iteration order (as the original does).
                let text = self
                    .timings
                    .iter()
                    .map(|(k, v)| format!("{}:{:.2}ms", k, v.as_secs_f64() * 1000.0))
                    .collect::<Vec<_>>()
                    .join(" ");
                let _ = &parts;
                panels.push(("Debug".to_string(), format!("Debug: {}", text)));
            }
            if let Some(info) = &self.info {
                panels.push(("Info".to_string(), info.clone()));
            }
        }
        let panel_heights: Vec<usize> = panels
            .iter()
            .map(|(_, content)| 1 + wrap_text(content, width).len())
            .collect();
        let (header_h, body_h, sep_h, help_h) = layout(height, &panel_heights);
        self.body_height = body_h;

        // Make sure the current selection is visible.
        match self.view {
            View::Flame => {
                if body_h > 0 {
                    let depth = self.tree.nodes[self.selected].depth;
                    if depth < self.flame_offset {
                        self.flame_offset = depth;
                    } else if depth >= self.flame_offset + body_h {
                        self.flame_offset = depth - body_h + 1;
                    }
                }
            }
            View::Top => {
                let (displayed, _) = self.displayed_top_indices();
                if !displayed.is_empty() && body_h > 1 {
                    let eff = self.top_selected.min(displayed.len() - 1);
                    let rows = body_h - 1;
                    if eff < self.top_offset {
                        self.top_offset = eff;
                    } else if eff >= self.top_offset + rows {
                        self.top_offset = eff - rows + 1;
                    }
                }
            }
        }

        let mut buf = Buffer::new(width, height);
        if header_h > 0 {
            self.draw_header(&mut buf, width, header_h);
        }
        match self.view {
            View::Flame => self.draw_flame(&mut buf, header_h, body_h),
            View::Top => self.draw_top(&mut buf, header_h, body_h),
        }

        let mut y = header_h + body_h;
        for ((title, content), &ph) in panels.iter().zip(panel_heights.iter()) {
            if y >= height {
                break;
            }
            self.draw_panel(&mut buf, y, width, title, content);
            y += ph;
        }
        if sep_h > 0 && y < height {
            buf.draw_text(0, y, &"─".repeat(width), Style::plain(), width);
            y += 1;
        }
        if help_h > 0 && y < height {
            self.draw_help(&mut buf, y, width);
        }

        let mut out = buf.render();
        if self.searching {
            // Place the cursor at the end of the search input's last line.
            let panel_y = header_h + body_h;
            let lines = wrap_text(&self.input.text(), width);
            let cursor_y = panel_y + lines.len();
            out.push_str(&format!(
                "\x1b[?25h\x1b[{};{}H",
                cursor_y + 1,
                self.input.cursor + 1
            ));
        } else {
            out.push_str("\x1b[?25l");
        }
        let render_started = Instant::now();
        terminal.write_str(&out)?;
        self.timings.insert("render".to_string(), render_started.elapsed());
        Ok(())
    }

    fn draw_header(&self, buf: &mut Buffer, width: usize, header_h: usize) {
        // Top rule.
        buf.draw_text(0, 0, &"─".repeat(width), Style::plain(), width);
        if header_h < 2 {
            return;
        }
        let y = 1;
        let right_w = width.min(16);
        let left_w = if width >= 36 { 20 } else { width.saturating_sub(right_w) };
        let mid_w = width.saturating_sub(left_w).saturating_sub(right_w);
        let mid_x = left_w;
        let right_x = left_w + mid_w;

        let title_style = Style { fg: Colour::Yellow, bg: Colour::Reset, bold: true, reverse: false };
        let bold = Style { fg: Colour::Reset, bg: Colour::Reset, bold: true, reverse: false };
        let mut x = 0usize;
        let mut left_remaining = left_w;
        let draw_span = |buf: &mut Buffer, x: &mut usize, rem: &mut usize, text: &str, style: Style| {
            if *rem == 0 {
                return;
            }
            let used = buf.draw_text(*x, y, text, style, *rem);
            *x += used;
            *rem = (*rem).saturating_sub(used);
        };
        draw_span(buf, &mut x, &mut left_remaining, " ", Style::plain());
        match self.view {
            View::Flame => {
                draw_span(buf, &mut x, &mut left_remaining, "[Flamegraph]", title_style);
                draw_span(buf, &mut x, &mut left_remaining, " | ", Style::plain());
                draw_span(buf, &mut x, &mut left_remaining, "Top", bold);
            }
            View::Top => {
                draw_span(buf, &mut x, &mut left_remaining, "Flamegraph", bold);
                draw_span(buf, &mut x, &mut left_remaining, " | ", Style::plain());
                draw_span(buf, &mut x, &mut left_remaining, "[Top]", title_style);
            }
        }

        if mid_w > 0 {
            let label_w = str_width(&self.label);
            let start = if label_w <= mid_w {
                mid_x + (mid_w - label_w) / 2
            } else {
                mid_x
            };
            buf.draw_text(start, y, &self.label, bold, mid_w.saturating_sub(start - mid_x));
        }
        if right_w > 0 {
            buf.draw_text(right_x, y, "flamelens v0.3.1", bold, right_w);
        }
        if header_h >= 3 {
            buf.draw_text(0, 2, &"─".repeat(width), Style::plain(), width);
        }
    }

    fn draw_panel(&self, buf: &mut Buffer, y: usize, width: usize, title: &str, content: &str) {
        let title_text = format!("{} ", title);
        let title_w = str_width(&title_text);
        let title_style = Style { fg: Colour::Yellow, bg: Colour::Reset, bold: true, reverse: false };
        buf.draw_text(0, y, &title_text, title_style, width);
        if width > title_w {
            buf.draw_text(title_w, y, &"─".repeat(width - title_w), Style::plain(), width - title_w);
        }
        for (i, line) in wrap_text(content, width).iter().enumerate() {
            buf.draw_text(0, y + 1 + i, line, Style::plain(), width);
        }
    }

    fn help_items(&self) -> Vec<(&'static str, &'static str)> {
        match self.view {
            View::Flame => {
                let mut items = vec![
                    ("hjkl", "move cursor"),
                    ("f/b", "scroll"),
                    ("enter/esc", "zoom"),
                    ("/", "search"),
                    ("#", "search like cursor"),
                ];
                if self.search.is_some() {
                    items.push(("n/N", "next/prev search"));
                }
                items.push(("r", "reset"));
                items.push(("tab", "switch view"));
                items.push(("q", "quit"));
                items
            }
            View::Top => vec![
                ("j/k", "move cursor"),
                ("f/b", "scroll"),
                ("1", "sort by total"),
                ("2", "sort by own"),
                ("/", "filter"),
                ("r", "reset"),
                ("tab", "switch view"),
                ("q", "quit"),
            ],
        }
    }

    fn draw_help(&self, buf: &mut Buffer, y: usize, width: usize) {
        let key_style = Style { fg: Colour::Yellow, bg: Colour::Reset, bold: true, reverse: false };
        // Build spans: each item is " [key: description]".
        let mut spans: Vec<(String, Style)> = Vec::new();
        for (key, desc) in self.help_items() {
            spans.push((" [".to_string(), Style::plain()));
            spans.push((key.to_string(), key_style));
            spans.push((format!(": {}]", desc), Style::plain()));
        }
        if self.view == View::Top {
            spans.push((" ".to_string(), Style::plain()));
        }
        let total_w: usize = spans.iter().map(|(s, _)| str_width(s)).sum();
        let start = if total_w <= width {
            match self.view {
                View::Flame => (width - total_w) / 2,
                View::Top => (width - total_w) / 2,
            }
        } else {
            0
        };
        let mut x = start;
        for (text, style) in spans {
            if x >= width {
                break;
            }
            let used = buf.draw_text(x, y, &text, style, width - x);
            if used == 0 && str_width(&text) > 0 {
                // Text was entirely beyond the available width.
                if x >= width {
                    break;
                }
                // Still advance by nothing; avoid an infinite loop.
                // (draw_text already stops at the boundary.)
                // Force a stop if nothing could be drawn and we are at edge.
                // Otherwise continue with the next span.
                // To be safe, break when remaining width is zero.
                if width - x == 0 {
                    break;
                }
                // If the span simply did not fit, skip it.
                // (This happens for a wide grapheme at the last column.)
                continue;
            }
            x += used;
        }
    }

    fn draw_flame(&self, buf: &mut Buffer, body_y: usize, body_h: usize) {
        if body_h == 0 {
            return;
        }
        let width = buf.width;
        let frames = self.display_frames.clone();
        for frame in &frames {
            if frame.depth < self.flame_offset {
                continue;
            }
            let rel = frame.depth - self.flame_offset;
            if rel >= body_h {
                continue;
            }
            let y = body_y + rel;
            let node = frame.node;
            let (t, base) = frame_colour(&self.tree.nodes[node].colour_key);
            let mut bg = base;
            let mut fg = if t > 0.47389 {
                Colour::Rgb(10, 10, 10)
            } else {
                Colour::Rgb(225, 225, 225)
            };
            let is_match = match &self.search {
                Some(re) => re.is_match(self.tree.search_name(node)),
                None => false,
            };
            if is_match {
                bg = Colour::Rgb(10, 35, 150);
                fg = Colour::Rgb(225, 225, 225);
            }
            if self.trail.contains(&node) {
                bg = dim_colour(bg);
                fg = Colour::Rgb(225, 225, 225);
            }
            if node == self.selected {
                bg = Colour::Rgb(250, 250, 250);
                fg = Colour::Rgb(10, 10, 10);
            }
            let style = Style::with_fg_bg(fg, bg);
            buf.fill_rect(frame.x, y, frame.width, 1, style);
            // Label: a leading space followed by the (possibly
            // search-highlighted) frame name.
            let mut cur_x = frame.x;
            let mut remaining = frame.width;
            let used = buf.draw_text(cur_x, y, " ", style, remaining);
            cur_x += used;
            remaining -= used;
            let name = self.tree.display_name(node).to_string();
            if remaining > 0 {
                if is_match {
                    if let Some(re) = &self.search {
                        let red = Style { fg: Colour::Rgb(225, 10, 10), bg, bold: true, reverse: false };
                        let matches = re.find_iter(&name);
                        let mut pos = 0usize;
                        for (s, e) in matches {
                            if s > pos && remaining > 0 {
                                let seg = &name[pos..s];
                                let u = buf.draw_text(cur_x, y, seg, style, remaining);
                                cur_x += u;
                                remaining -= u;
                            }
                            if e > s && remaining > 0 {
                                let seg = &name[s..e];
                                let u = buf.draw_text(cur_x, y, seg, red, remaining);
                                cur_x += u;
                                remaining -= u;
                            }
                            if e > pos {
                                pos = e;
                            }
                        }
                        if pos < name.len() && remaining > 0 {
                            buf.draw_text(cur_x, y, &name[pos..], style, remaining);
                        }
                    }
                } else {
                    buf.draw_text(cur_x, y, &name, style, remaining);
                }
            }
            let _ = width;
        }
    }

    fn draw_top(&self, buf: &mut Buffer, body_y: usize, body_h: usize) {
        if body_h == 0 {
            return;
        }
        let (displayed, _) = self.displayed_top_indices();
        let mut total_strings: Vec<String> = Vec::new();
        let mut own_strings: Vec<String> = Vec::new();
        for &i in &displayed {
            total_strings.push(percent_string(self.top_entries[i].total, self.total));
            own_strings.push(percent_string(self.top_entries[i].own, self.total));
        }
        let total_w = total_strings.iter().map(|s| str_width(s)).max().unwrap_or(0);
        let own_w = own_strings.iter().map(|s| str_width(s)).max().unwrap_or(0);
        let total_col_w = if total_w == 0 { 0 } else { total_w + 2 };
        let own_col_w = if own_w == 0 { 0 } else { own_w + 2 };
        let x_total = 0usize;
        let x_own = x_total + total_col_w + 1;
        let x_name = x_own + own_col_w + 1;

        // Header.
        let header_style = Style { fg: Colour::Reset, bg: Colour::Reset, bold: true, reverse: true };
        buf.fill_rect(0, body_y, buf.width, 1, header_style);
        let total_label = if self.top_sort == TopSort::Total { "Total [▼]" } else { "Total" };
        let own_label = if self.top_sort == TopSort::Own { "Own [▼]" } else { "Own" };
        buf.draw_text(x_total, body_y, total_label, header_style, total_col_w);
        buf.draw_text(x_own, body_y, own_label, header_style, own_col_w);
        if x_name < buf.width {
            buf.draw_text(x_name, body_y, "Name", header_style, buf.width - x_name);
        }

        if body_h < 2 || displayed.is_empty() {
            return;
        }
        let rows_visible = body_h - 1;
        let eff_selected = self.top_selected.min(displayed.len() - 1);
        for pos in self.top_offset..displayed.len() {
            if pos - self.top_offset >= rows_visible {
                break;
            }
            let y = body_y + 1 + (pos - self.top_offset);
            let idx = displayed[pos];
            let style = if pos == eff_selected {
                Style::with_fg_bg(Colour::Reset, Colour::Rgb(65, 65, 65))
            } else {
                Style::plain()
            };
            buf.fill_rect(0, y, buf.width, 1, style);
            // total_strings/own_strings are in displayed order.
            let dpos = pos;
            buf.draw_text(x_total, y, &total_strings[dpos], style, total_col_w);
            buf.draw_text(x_own, y, &own_strings[dpos], style, own_col_w);
            if x_name < buf.width {
                buf.draw_text(x_name, y, &self.top_entries[idx].name, style, buf.width - x_name);
            }
        }
    }

    // ---------------- key handling ----------------

    fn handle_key(&mut self, key: KeyEvent) {
        if self.searching {
            self.handle_search_key(key);
            return;
        }
        // Quit keys are honoured regardless of view.  `q` quits with any
        // modifier, as does Ctrl-C.
        if key.code == KeyCode::Char('c') && key.ctrl {
            self.quit = true;
            return;
        }
        if key.code == KeyCode::Char('q') {
            self.quit = true;
            return;
        }
        if key.code == KeyCode::Tab {
            self.info = None;
            self.view = match self.view {
                View::Flame => View::Top,
                View::Top => View::Flame,
            };
            return;
        }
        if key.code == KeyCode::Char('/') {
            self.info = None;
            self.searching = true;
            self.input.clear();
            return;
        }
        if key.code == KeyCode::Char('r') {
            self.reset();
            return;
        }
        match self.view {
            View::Flame => self.handle_flame_key(key),
            View::Top => self.handle_top_key(key),
        }
    }

    fn handle_search_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Enter => {
                self.searching = false;
                let pattern = self.input.text();
                self.apply_search(&pattern);
            }
            KeyCode::Esc => {
                self.searching = false;
            }
            KeyCode::Backspace => {
                if key.alt {
                    self.input.delete_prev_word();
                } else if !key.ctrl {
                    self.input.delete_prev_char();
                }
            }
            KeyCode::Delete => {
                if key.ctrl {
                    self.input.delete_next_word();
                } else if !key.alt {
                    self.input.delete_next_char();
                }
            }
            KeyCode::Left => {
                if key.ctrl {
                    self.input.cursor = self.input.prev_word_boundary(self.input.cursor);
                } else if !key.alt && !key.shift {
                    self.input.cursor = self.input.cursor.saturating_sub(1);
                }
            }
            KeyCode::Right => {
                if key.ctrl {
                    self.input.cursor = self.input.next_word_boundary(self.input.cursor);
                } else if !key.alt && !key.shift {
                    if self.input.cursor < self.input.chars.len() {
                        self.input.cursor += 1;
                    }
                }
            }
            KeyCode::Home => {
                self.input.cursor = 0;
            }
            KeyCode::End => {
                self.input.cursor = self.input.chars.len();
            }
            KeyCode::Char(c) => {
                if key.ctrl {
                    match c {
                        'a' => self.input.cursor = 0,
                        'e' => self.input.cursor = self.input.chars.len(),
                        'b' => self.input.cursor = self.input.cursor.saturating_sub(1),
                        'f' => {
                            if self.input.cursor < self.input.chars.len() {
                                self.input.cursor += 1;
                            }
                        }
                        'h' => self.input.delete_prev_char(),
                        'k' => {
                            self.input.chars.drain(self.input.cursor..);
                        }
                        'u' => self.input.clear(),
                        'w' => self.input.delete_prev_word(),
                        _ => {}
                    }
                } else if !key.alt {
                    self.input.insert(c);
                }
            }
            _ => {}
        }
    }

    fn displayed_node_set(&self) -> HashSet<usize> {
        self.display_frames.iter().map(|f| f.node).collect()
    }

    fn handle_flame_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Char('h') | KeyCode::Left => {
                self.info = None;
                self.move_sibling(-1);
            }
            KeyCode::Char('l') | KeyCode::Right => {
                self.info = None;
                self.move_sibling(1);
            }
            KeyCode::Char('j') | KeyCode::Down => {
                self.info = None;
                self.move_down();
            }
            KeyCode::Char('k') | KeyCode::Up => {
                self.info = None;
                self.move_up();
            }
            KeyCode::Char('f') => {
                self.info = None;
                self.flame_scroll(ScrollKind::Down);
            }
            KeyCode::Char('b') => {
                self.info = None;
                self.flame_scroll(ScrollKind::Up);
            }
            KeyCode::Char('G') => {
                self.info = None;
                self.flame_scroll(ScrollKind::Bottom);
            }
            KeyCode::Char('g') => {
                self.info = None;
                self.flame_scroll(ScrollKind::Top);
            }
            KeyCode::Enter => {
                self.info = None;
                if self.selected == 0 {
                    if let Some(z) = self.zoom.take() {
                        self.selected = z;
                    }
                } else {
                    self.zoom = Some(self.selected);
                }
            }
            KeyCode::Esc => {
                self.info = None;
                if let Some(z) = self.zoom.take() {
                    self.selected = z;
                }
            }
            KeyCode::Char('#') => {
                self.info = None;
                self.search_like_selected();
            }
            KeyCode::Char('n') => {
                self.info = None;
                self.next_match(false);
            }
            KeyCode::Char('N') => {
                self.info = None;
                self.next_match(true);
            }
            _ => {}
        }
    }

    fn move_sibling(&mut self, dir: i32) {
        let Some(parent) = self.tree.nodes[self.selected].parent else {
            return;
        };
        let displayed = self.displayed_node_set();
        let siblings = self.tree.nodes[parent].children.clone();
        let tree_pos = siblings.iter().position(|&id| id == self.selected);
        let displayed_sibs: Vec<usize> = siblings.iter().copied().filter(|id| displayed.contains(id)).collect();
        if let Some(pos) = displayed_sibs.iter().position(|&id| id == self.selected) {
            let next = pos as i32 + dir;
            if next >= 0 && (next as usize) < displayed_sibs.len() {
                self.selected = displayed_sibs[next as usize];
            }
        } else if let Some(tp) = tree_pos {
            if dir < 0 {
                if let Some(&cand) = displayed_sibs
                    .iter()
                    .filter(|&&id| siblings.iter().position(|&s| s == id).unwrap_or(usize::MAX) < tp)
                    .last()
                {
                    self.selected = cand;
                }
            } else if let Some(&cand) = displayed_sibs
                .iter()
                .find(|&&id| siblings.iter().position(|&s| s == id).unwrap_or(0) > tp)
            {
                self.selected = cand;
            }
        }
    }

    fn move_down(&mut self) {
        let displayed = self.displayed_node_set();
        let children: Vec<usize> = self
            .display_frames
            .iter()
            .filter(|f| self.tree.nodes[f.node].parent == Some(self.selected))
            .map(|f| f.node)
            .collect();
        let _ = displayed;
        let mut best: Option<usize> = None;
        for cand in children {
            match best {
                None => best = Some(cand),
                Some(b) => {
                    if self.tree.nodes[cand].samples >= self.tree.nodes[b].samples {
                        best = Some(cand);
                    }
                }
            }
        }
        if let Some(b) = best {
            self.selected = b;
        }
    }

    fn move_up(&mut self) {
        if let Some(parent) = self.tree.nodes[self.selected].parent {
            self.selected = parent;
        }
    }

    fn flame_scroll(&mut self, kind: ScrollKind) {
        let page = self.body_height;
        if page == 0 {
            return;
        }
        let total_levels = self
            .display_frames
            .iter()
            .map(|f| f.depth)
            .max()
            .map(|d| d + 1)
            .unwrap_or(1);
        let max_offset = total_levels.saturating_sub(page);
        let new_offset = match kind {
            ScrollKind::Down => (self.flame_offset + page).min(max_offset),
            ScrollKind::Up => self.flame_offset.saturating_sub(page),
            ScrollKind::Bottom => max_offset,
            ScrollKind::Top => 0,
        };
        if new_offset != self.flame_offset {
            self.flame_offset = new_offset;
            let first = self
                .display_frames
                .iter()
                .filter(|f| f.depth == new_offset)
                .min_by(|a, b| a.exact_x.partial_cmp(&b.exact_x).unwrap_or(Ordering::Equal));
            if let Some(f) = first {
                self.selected = f.node;
            }
        }
    }

    fn next_match(&mut self, previous: bool) {
        let Some(re) = self.search.clone() else {
            return;
        };
        if self.display_frames.is_empty() {
            return;
        }
        let cur_idx = self.display_frames.iter().position(|f| f.node == self.selected);
        let target = match cur_idx {
            Some(idx) => {
                if previous {
                    self.display_frames[..idx]
                        .iter()
                        .rev()
                        .find(|f| re.is_match(self.tree.search_name(f.node)))
                        .map(|f| f.node)
                } else {
                    self.display_frames[idx + 1..]
                        .iter()
                        .find(|f| re.is_match(self.tree.search_name(f.node)))
                        .map(|f| f.node)
                }
            }
            None => {
                if previous {
                    self.display_frames
                        .iter()
                        .rev()
                        .find(|f| re.is_match(self.tree.search_name(f.node)))
                        .map(|f| f.node)
                } else {
                    self.display_frames
                        .iter()
                        .find(|f| re.is_match(self.tree.search_name(f.node)))
                        .map(|f| f.node)
                }
            }
        };
        if let Some(node) = target {
            self.selected = node;
        }
    }

    fn handle_top_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Char('j') | KeyCode::Down => {
                self.info = None;
                let (displayed, _) = self.displayed_top_indices();
                if !displayed.is_empty() {
                    self.top_selected = (self.top_selected + 1).min(displayed.len() - 1);
                }
            }
            KeyCode::Char('k') | KeyCode::Up => {
                self.info = None;
                self.top_selected = self.top_selected.saturating_sub(1);
            }
            KeyCode::Char('f') => {
                self.info = None;
                let (displayed, _) = self.displayed_top_indices();
                if !displayed.is_empty() {
                    let page = self.body_height.max(1);
                    self.top_selected = (self.top_selected + page).min(displayed.len() - 1);
                    self.top_offset = self.top_selected;
                }
            }
            KeyCode::Char('b') => {
                self.info = None;
                let (displayed, _) = self.displayed_top_indices();
                if !displayed.is_empty() {
                    let page = self.body_height.max(1);
                    self.top_selected = self.top_selected.saturating_sub(page);
                    self.top_offset = self.top_selected;
                }
            }
            KeyCode::Char('1') => {
                self.info = None;
                self.top_sort = TopSort::Total;
                sort_top(&mut self.top_entries, TopSort::Total);
            }
            KeyCode::Char('2') => {
                self.info = None;
                self.top_sort = TopSort::Own;
                sort_top(&mut self.top_entries, TopSort::Own);
            }
            KeyCode::Enter => {
                self.info = None;
                let (displayed, _) = self.displayed_top_indices();
                if !displayed.is_empty() {
                    let eff = self.top_selected.min(displayed.len() - 1);
                    let name = self.top_entries[displayed[eff]].name.clone();
                    let pattern = format!("^{}$", regex_engine::escape_literal(&name));
                    self.apply_search(&pattern);
                }
                self.view = View::Flame;
            }
            _ => {}
        }
    }
}

#[derive(Clone, Copy)]
enum ScrollKind {
    Down,
    Up,
    Bottom,
    Top,
}

fn run_app(args: Args, label: String, data: String) -> io::Result<()> {
    let records = parse_records(&data);
    let echo = args.echo;
    let mut app = App::new(&args, label, data, &records);
    let mut terminal = Terminal::new()?;
    let result = app.run(&mut terminal);
    terminal.restore();
    result?;
    if echo {
        println!("{}", app.data);
    }
    Ok(())
}
