s=s.replace("""            if is_match {
                bg = Colour::Rgb(10, 35, 150);
                fg = Colour::Rgb(225, 225, 225);
            }
            if self.trail.contains(&node) {""",
"""            if is_match {
                bg = Colour::Rgb(10, 35, 150);
                fg = Colour::Rgb(225, 225, 225);
            }
            if self.selected != 0
                && node != self.selected
                && self.tree.search_name(node) == self.tree.search_name(self.selected)
            {
                bg = Colour::Rgb(10, 35, 150);
                fg = Colour::Rgb(225, 225, 225);
            }
            if self.trail.contains(&node) {""")
# top name highlight: replace simple name draw in draw_top
s=s.replace("""            if x_name < buf.width {
                buf.draw_text(x_name, y, &self.top_entries[idx].name, style, buf.width - x_name);
            }""",
"""            if x_name < buf.width {
                let entry_name = self.top_entries[idx].name.clone();
                let name_is_match = match &self.search {
                    Some(re) => re.is_match(&entry_name),
                    None => false,
                };
                if name_is_match {
                    if let Some(re) = &self.search {
                        let red = Style { fg: Colour::Rgb(225, 10, 10), bg: style.bg, bold: true, reverse: false };
                        let mut cur_x = x_name;
                        let mut remaining = buf.width - x_name;
                        let matches = re.find_iter(&entry_name);
                        let mut pos = 0usize;
                        for (ms, me) in matches {
                            if ms > pos && remaining > 0 {
                                let u = buf.draw_text(cur_x, y, &entry_name[pos..ms], style, remaining);
                                cur_x += u;
                                remaining -= u;
                            }
                            if me > ms && remaining > 0 {
                                let u = buf.draw_text(cur_x, y, &entry_name[ms..me], red, remaining);
                                cur_x += u;
                                remaining -= u;
                            }
                            if me > pos {
                                pos = me;
                            }
                        }
                        if pos < entry_name.len() && remaining > 0 {
                            buf.draw_text(cur_x, y, &entry_name[pos..], style, remaining);
                        }
                    }
                } else {
                    buf.draw_text(x_name, y, &entry_name, style, buf.width - x_name);
                }
            }""")
p.write_text(s)
